begin;

insert into public.paid_mock_test_question_banks (test_slug, questions) values
  ('pma-long-course-159-mock-test-2', '[{"id":1,"question_text":"Verbal Intelligence: Pen : Write :: Knife : ?","option_a":"Sharp","option_b":"Kitchen","option_c":"Steel","option_d":"Cut","section":"Verbal Intelligence","correct_option":"D","difficulty":"Easy","explanation":"Cut. A pen is used to write; a knife is used to cut (tool : function)."},{"id":2,"question_text":"Verbal Intelligence: Foot : Shoe :: Hand : ?","option_a":"Glove","option_b":"Finger","option_c":"Wrist","option_d":"Palm","section":"Verbal Intelligence","correct_option":"A","difficulty":"Easy","explanation":"Glove. A shoe covers the foot; a glove covers the hand (body part : covering)."},{"id":3,"question_text":"Verbal Intelligence: Doctor : Patient :: Lawyer : ?","option_a":"Court","option_b":"Judge","option_c":"Law","option_d":"Client","section":"Verbal Intelligence","correct_option":"D","difficulty":"Easy","explanation":"Client. A doctor serves a patient; a lawyer serves a client (professional : person served)."},{"id":4,"question_text":"Verbal Intelligence: Thermometer : Temperature :: Barometer : ?","option_a":"Humidity","option_b":"Rainfall","option_c":"Atmospheric pressure","option_d":"Wind speed","section":"Verbal Intelligence","correct_option":"C","difficulty":"Medium","explanation":"Atmospheric pressure. Instrument : quantity it measures. A barometer measures air pressure."},{"id":5,"question_text":"Verbal Intelligence: Soldier : Army :: Sailor : ?","option_a":"Ship","option_b":"Sea","option_c":"Port","option_d":"Navy","section":"Verbal Intelligence","correct_option":"D","difficulty":"Medium","explanation":"Navy. A soldier serves in the army; a sailor serves in the navy (member : service)."},{"id":6,"question_text":"Verbal Intelligence: Famine : Food :: Drought : ?","option_a":"Water","option_b":"Heat","option_c":"Crops","option_d":"Sand","section":"Verbal Intelligence","correct_option":"A","difficulty":"Medium","explanation":"Water. Famine is extreme shortage of food; drought is extreme shortage of water (rain)."},{"id":7,"question_text":"Verbal Intelligence: Verbose : Concise :: Lavish : ?","option_a":"Frugal","option_b":"Rich","option_c":"Generous","option_d":"Wasteful","section":"Verbal Intelligence","correct_option":"A","difficulty":"Hard","explanation":"Frugal. Both pairs are antonyms. Verbose (wordy) is opposite to concise; lavish (extravagant) is opposite to frugal (thrifty)."},{"id":8,"question_text":"Verbal Intelligence: Anemometer : Wind speed :: Seismograph : ?","option_a":"Volcanoes","option_b":"Earthquakes","option_c":"Rainfall","option_d":"Sound Odd One Out","section":"Verbal Intelligence","correct_option":"B","difficulty":"Hard","explanation":"Earthquakes. Instrument : what it measures. A seismograph records earthquake (seismic) waves."},{"id":9,"question_text":"Verbal Intelligence: Find the odd one out: Apple, Mango, Potato, Banana","option_a":"Potato","option_b":"Apple","option_c":"Mango","option_d":"Banana","section":"Verbal Intelligence","correct_option":"A","difficulty":"Easy","explanation":"Potato. Potato is a vegetable; the others are fruits."},{"id":10,"question_text":"Verbal Intelligence: Find the odd one out: Lahore, Karachi, Quetta, Kabul","option_a":"Lahore","option_b":"Kabul","option_c":"Karachi","option_d":"Quetta","section":"Verbal Intelligence","correct_option":"B","difficulty":"Easy","explanation":"Kabul. Kabul is in Afghanistan; the others are cities of Pakistan."},{"id":11,"question_text":"Verbal Intelligence: Find the odd one out: Sword, Dagger, Bayonet, Helmet","option_a":"Sword","option_b":"Dagger","option_c":"Helmet","option_d":"Bayonet","section":"Verbal Intelligence","correct_option":"C","difficulty":"Medium","explanation":"Helmet. A helmet is protective equipment; the others are bladed weapons."},{"id":12,"question_text":"Verbal Intelligence: Find the odd one out: Rose, Jasmine, Lotus, Oak","option_a":"Rose","option_b":"Jasmine","option_c":"Oak","option_d":"Lotus","section":"Verbal Intelligence","correct_option":"C","difficulty":"Medium","explanation":"Oak. Oak is a tree; the others are flowers."},{"id":13,"question_text":"Verbal Intelligence: Find the odd one out: 11, 13, 17, 21","option_a":"11","option_b":"13","option_c":"21","option_d":"17","section":"Verbal Intelligence","correct_option":"C","difficulty":"Medium","explanation":"21. 11, 13 and 17 are prime numbers; 21 = 3 × 7 is not."},{"id":14,"question_text":"Verbal Intelligence: Find the odd one out: 8, 27, 64, 100","option_a":"8","option_b":"27","option_c":"64","option_d":"100 Number Series","section":"Verbal Intelligence","correct_option":"D","difficulty":"Hard","explanation":"100. 8 = 2³, 27 = 3³, 64 = 4³ are perfect cubes; 100 is not."},{"id":15,"question_text":"Verbal Intelligence: Find the next number: 3, 6, 9, 12, ?","option_a":"15","option_b":"14","option_c":"16","option_d":"18","section":"Verbal Intelligence","correct_option":"A","difficulty":"Easy","explanation":"15. Add 3 each time."},{"id":16,"question_text":"Verbal Intelligence: Find the next number: 2, 6, 18, 54, ?","option_a":"108","option_b":"162","option_c":"72","option_d":"160","section":"Verbal Intelligence","correct_option":"B","difficulty":"Easy","explanation":"162. Multiply by 3 each time."},{"id":17,"question_text":"Verbal Intelligence: Find the next number: 1, 4, 9, 16, 25, ?","option_a":"30","option_b":"34","option_c":"49","option_d":"36","section":"Verbal Intelligence","correct_option":"D","difficulty":"Medium","explanation":"36. Perfect squares: 1², 2², 3², 4², 5², so the next is 6² = 36."},{"id":18,"question_text":"Verbal Intelligence: Find the next number: 5, 8, 14, 26, ?","option_a":"38","option_b":"40","option_c":"52","option_d":"50","section":"Verbal Intelligence","correct_option":"D","difficulty":"Medium","explanation":"50. Differences are 3, 6, 12 (doubling), so the next difference is 24: 26 + 24 = 50."},{"id":19,"question_text":"Verbal Intelligence: Find the next number: 2, 3, 5, 7, 11, ?","option_a":"12","option_b":"13","option_c":"14","option_d":"15","section":"Verbal Intelligence","correct_option":"B","difficulty":"Medium","explanation":"13. Consecutive prime numbers: after 11 comes 13."},{"id":20,"question_text":"Verbal Intelligence: Find the next number: 4, 9, 19, 39, ?","option_a":"78","option_b":"77","option_c":"59","option_d":"79","section":"Verbal Intelligence","correct_option":"D","difficulty":"Hard","explanation":"79. Each term = previous × 2 + 1: 4→9→19→39→79."},{"id":21,"question_text":"Verbal Intelligence: Find the next number: 1, 2, 6, 24, 120, ?","option_a":"240","option_b":"600","option_c":"720","option_d":"840","section":"Verbal Intelligence","correct_option":"C","difficulty":"Hard","explanation":"720. Factorials: 1!, 2!, 3!, 4!, 5!, next 6! = 720."},{"id":22,"question_text":"Verbal Intelligence: Find the next number: 2, 5, 10, 17, 26, ?","option_a":"37","option_b":"35","option_c":"36","option_d":"38 Letter Series","section":"Verbal Intelligence","correct_option":"A","difficulty":"Hard","explanation":"37. Pattern n² + 1: 2, 5, 10, 17, 26, next is 6²+1 = 37."},{"id":23,"question_text":"Verbal Intelligence: Find the next letter: A, C, E, G, ?","option_a":"H","option_b":"J","option_c":"I","option_d":"K","section":"Verbal Intelligence","correct_option":"C","difficulty":"Easy","explanation":"I. Skip one letter each time (+2): A, C, E, G, I."},{"id":24,"question_text":"Verbal Intelligence: Find the next letter: Z, X, V, T, ?","option_a":"S","option_b":"Q","option_c":"R","option_d":"P","section":"Verbal Intelligence","correct_option":"C","difficulty":"Easy","explanation":"R. Move back two letters each time: Z, X, V, T, R."},{"id":25,"question_text":"Verbal Intelligence: Find the next letter: B, E, H, K, ?","option_a":"L","option_b":"M","option_c":"O","option_d":"N","section":"Verbal Intelligence","correct_option":"D","difficulty":"Medium","explanation":"N. Each letter is 3 places after the previous: B, E, H, K, N."},{"id":26,"question_text":"Verbal Intelligence: Find the next group: AZ, BY, CX, ?","option_a":"DV","option_b":"EW","option_c":"DX","option_d":"DW","section":"Verbal Intelligence","correct_option":"D","difficulty":"Medium","explanation":"DW. First letters go forward (A, B, C, D) while second letters go backward (Z, Y, X, W)."},{"id":27,"question_text":"Verbal Intelligence: Find the next group: AB, DE, GH, JK, ?","option_a":"LM","option_b":"MO","option_c":"MN","option_d":"NO","section":"Verbal Intelligence","correct_option":"C","difficulty":"Hard","explanation":"MN. Each group moves 3 letters ahead: AB, DE, GH, JK, MN."},{"id":28,"question_text":"Verbal Intelligence: Which letter is the 7th to the left of the 20th letter from the left end of the English alphabet?","option_a":"N","option_b":"L","option_c":"T","option_d":"M Coding-Decoding","section":"Verbal Intelligence","correct_option":"D","difficulty":"Hard","explanation":"M. 20th letter is T. Seventh to its left is the 13th letter: M."},{"id":29,"question_text":"Verbal Intelligence: If CAT is coded as DBU, how is DOG coded?","option_a":"EOH","option_b":"EPH","option_c":"CNF","option_d":"EPG","section":"Verbal Intelligence","correct_option":"B","difficulty":"Easy","explanation":"EPH. Each letter is moved one place forward: D→E, O→P, G→H, so EPH."},{"id":30,"question_text":"Verbal Intelligence: If A = 1, B = 2, C = 3 … Z = 26, what is the sum of the values of the letters in FACE?","option_a":"15","option_b":"14","option_c":"16","option_d":"17","section":"Verbal Intelligence","correct_option":"A","difficulty":"Easy","explanation":"15. F=6, A=1, C=3, E=5; total = 15."},{"id":31,"question_text":"Verbal Intelligence: In a certain code PAKISTAN is written as QBLJTUBO. How is ARMY written in that code?","option_a":"BQNX","option_b":"BSMZ","option_c":"BSNZ","option_d":"ASNZ","section":"Verbal Intelligence","correct_option":"C","difficulty":"Medium","explanation":"BSNZ. Each letter is moved one place forward: A→B, R→S, M→N, Y→Z, so BSNZ."},{"id":32,"question_text":"Verbal Intelligence: In a certain code LAHORE is written as EROHAL. How is QUETTA written in that code?","option_a":"ATTEQU","option_b":"ETTAUQ","option_c":"ATTEUQ","option_d":"ATEUTQ","section":"Verbal Intelligence","correct_option":"C","difficulty":"Medium","explanation":"ATTEUQ. The word is written backwards: QUETTA → ATTEUQ."},{"id":33,"question_text":"Verbal Intelligence: In a certain code MOUSE is written as PRXVH. How is GRAPE written in that code?","option_a":"JUDQH","option_b":"JUDSH","option_c":"JTDSH","option_d":"IUCSH","section":"Verbal Intelligence","correct_option":"B","difficulty":"Hard","explanation":"JUDSH. Each letter is moved 3 places forward: G→J, R→U, A→D, P→S, E→H, so JUDSH."},{"id":34,"question_text":"Verbal Intelligence: In a certain code HOME is written as IQNG. How is FARM written in that code?","option_a":"GBSN","option_b":"HCTO","option_c":"GDSP","option_d":"GCSO Blood Relations","section":"Verbal Intelligence","correct_option":"D","difficulty":"Hard","explanation":"GCSO. Letters are moved forward alternately by +1 and +2 (H+1, O+2, M+1, E+2 gives IQNG). FARM: F+1=G, A+2=C, R+1=S, M+2=O, so GCSO."},{"id":35,"question_text":"Verbal Intelligence: A is the brother of B. B is the sister of C. C is the father of D. How is A related to D?","option_a":"Uncle","option_b":"Father","option_c":"Brother","option_d":"Grandfather","section":"Verbal Intelligence","correct_option":"A","difficulty":"Easy","explanation":"Uncle. A and C are brothers (B is their sister). D is C''s child, so A is D''s uncle."},{"id":36,"question_text":"Verbal Intelligence: A man introduces a woman as the wife of the only son of his mother. How is the woman related to the man?","option_a":"His sister","option_b":"His wife","option_c":"His mother","option_d":"His daughter","section":"Verbal Intelligence","correct_option":"B","difficulty":"Easy","explanation":"His wife. The only son of his mother is the man himself. So the woman is his wife."},{"id":37,"question_text":"Verbal Intelligence: Pointing to a man, a woman says, \"He is the son of my mother''s only son.\" How is the man related to the woman?","option_a":"Nephew","option_b":"Son","option_c":"Brother","option_d":"Cousin","section":"Verbal Intelligence","correct_option":"A","difficulty":"Medium","explanation":"Nephew. Her mother''s only son is her brother; the man is the brother''s son, so her nephew."},{"id":38,"question_text":"Verbal Intelligence: Ali says, \"Ahmed''s mother is the only daughter of my mother.\" How is Ali related to Ahmed?","option_a":"Father","option_b":"Maternal uncle","option_c":"Paternal uncle","option_d":"Brother","section":"Verbal Intelligence","correct_option":"B","difficulty":"Medium","explanation":"Maternal uncle. The only daughter of Ali''s mother is Ali''s sister. She is Ahmed''s mother, so Ali is Ahmed''s mother''s brother: maternal uncle."},{"id":39,"question_text":"Verbal Intelligence: P is the brother of Q. Q is the sister of R. R is the mother of S. How is P related to S?","option_a":"Father","option_b":"Paternal uncle","option_c":"Maternal uncle","option_d":"Grandfather","section":"Verbal Intelligence","correct_option":"C","difficulty":"Hard","explanation":"Maternal uncle. P and R are siblings (brother and sister). S is R''s child, so P is S''s mother''s brother: maternal uncle."},{"id":40,"question_text":"Verbal Intelligence: Pointing to a girl, Bilal says, \"She is the daughter of the only son of my father''s father.\" How is the girl related to Bilal?","option_a":"Cousin","option_b":"Sister","option_c":"Niece","option_d":"Aunt Direction Sense","section":"Verbal Intelligence","correct_option":"B","difficulty":"Hard","explanation":"Sister. The only son of Bilal''s father''s father is Bilal''s own father. His daughter is Bilal''s sister."},{"id":41,"question_text":"Verbal Intelligence: A man walks 3 km east and then 4 km north. How far is he from his starting point?","option_a":"7 km","option_b":"5 km","option_c":"6 km","option_d":"4 km","section":"Verbal Intelligence","correct_option":"B","difficulty":"Easy","explanation":"5 km. Straight-line distance = √(3² + 4²) = √25 = 5 km."},{"id":42,"question_text":"Verbal Intelligence: A boy facing north turns right, then left, then left. Which direction is he facing now?","option_a":"East","option_b":"West","option_c":"North","option_d":"South","section":"Verbal Intelligence","correct_option":"B","difficulty":"Easy","explanation":"West. North → (right) East → (left) North → (left) West."},{"id":43,"question_text":"Verbal Intelligence: A man walks 10 m south, turns left and walks 10 m, then turns left again and walks 10 m. Where is he with respect to his starting point?","option_a":"10 m west","option_b":"10 m north","option_c":"10 m south","option_d":"10 m east","section":"Verbal Intelligence","correct_option":"D","difficulty":"Medium","explanation":"10 m east. South 10 m puts him at (0, −10). Left from south is east: (10, −10). Left from east is north: (10, 0), i.e. 10 m east of the start."},{"id":44,"question_text":"Verbal Intelligence: One morning Ali stands facing the sun. Which direction is his left hand pointing?","option_a":"South","option_b":"East","option_c":"North","option_d":"West","section":"Verbal Intelligence","correct_option":"C","difficulty":"Medium","explanation":"North. In the morning the sun is in the east, so he faces east. Left of east is north."},{"id":45,"question_text":"Verbal Intelligence: A man walks 6 km north, then 8 km east, then 6 km south. How far and in which direction is he from the start?","option_a":"8 km east","option_b":"14 km east","option_c":"10 km north-east","option_d":"8 km west","section":"Verbal Intelligence","correct_option":"A","difficulty":"Hard","explanation":"8 km east. The north and south legs cancel, leaving 8 km east."},{"id":46,"question_text":"Verbal Intelligence: A starts from a point and goes 4 km west, turns right and goes 3 km, turns right and goes 4 km, then turns left and goes 2 km. How far and in which direction is he from the start?","option_a":"5 km north","option_b":"7 km north","option_c":"5 km east","option_d":"3 km north Ranking and Order","section":"Verbal Intelligence","correct_option":"A","difficulty":"Hard","explanation":"5 km north. West 4 km: (−4, 0). Right (north) 3 km: (−4, 3). Right (east) 4 km: (0, 3). Left (north) 2 km: (0, 5). So 5 km due north."},{"id":47,"question_text":"Verbal Intelligence: In a class of 40 students, Ali ranks 12th from the top. What is his rank from the bottom?","option_a":"28th","option_b":"29th","option_c":"30th","option_d":"27th","section":"Verbal Intelligence","correct_option":"B","difficulty":"Easy","explanation":"29th. Rank from bottom = total − rank from top + 1 = 40 − 12 + 1 = 29."},{"id":48,"question_text":"Verbal Intelligence: In a row of 25 students, Zain is 10th from the left. What is his position from the right?","option_a":"15th","option_b":"16th","option_c":"14th","option_d":"17th","section":"Verbal Intelligence","correct_option":"B","difficulty":"Easy","explanation":"16th. 25 − 10 + 1 = 16."},{"id":49,"question_text":"Verbal Intelligence: A is taller than B, B is taller than C, and D is shorter than C. Who is the second tallest?","option_a":"A","option_b":"C","option_c":"D","option_d":"B","section":"Verbal Intelligence","correct_option":"D","difficulty":"Medium","explanation":"B. Order (tallest to shortest): A > B > C > D. The second tallest is B."},{"id":50,"question_text":"Verbal Intelligence: Among five friends P, Q, R, S and T: P is older than Q; Q is older than R; S is younger than R but older than T. Who is the second youngest?","option_a":"S","option_b":"R","option_c":"T","option_d":"Q","section":"Verbal Intelligence","correct_option":"A","difficulty":"Medium","explanation":"S. Age order (oldest to youngest): P > Q > R > S > T. Second youngest is S."},{"id":51,"question_text":"Verbal Intelligence: A student ranks 15th from the top and 20th from the bottom in a class. How many students are there in the class?","option_a":"35","option_b":"33","option_c":"36","option_d":"34","section":"Verbal Intelligence","correct_option":"D","difficulty":"Hard","explanation":"34. Total = 15 + 20 − 1 = 34 (the student is counted in both ranks)."},{"id":52,"question_text":"Verbal Intelligence: In a queue of 25 persons, Ali is 8th from the front and Bilal is 12th from the back. How many persons stand between them?","option_a":"4","option_b":"5","option_c":"6","option_d":"3 Syllogisms","section":"Verbal Intelligence","correct_option":"B","difficulty":"Hard","explanation":"5. Bilal is 25 − 12 + 1 = 14th from the front. Persons between = 14 − 8 − 1 = 5."},{"id":53,"question_text":"Verbal Intelligence: Statements: All soldiers are brave. Some brave persons are young. Conclusions: I. Some soldiers are young. II. All brave persons are soldiers.","option_a":"Only conclusion I follows","option_b":"Only conclusion II follows","option_c":"Both conclusions follow","option_d":"Neither conclusion follows","section":"Verbal Intelligence","correct_option":"D","difficulty":"Medium","explanation":"Neither conclusion follows. From ''some brave are young'' we cannot say the young ones are soldiers, and ''all soldiers are brave'' does not reverse to ''all brave are soldiers''. Neither follows."},{"id":54,"question_text":"Verbal Intelligence: Statements: All cats are animals. All animals are living beings. Conclusions: I. All cats are living beings. II. All living beings are cats.","option_a":"Only conclusion II follows","option_b":"Both conclusions follow","option_c":"Only conclusion I follows","option_d":"Neither conclusion follows","section":"Verbal Intelligence","correct_option":"C","difficulty":"Easy","explanation":"Only conclusion I follows. Cats ⊂ animals ⊂ living beings, so I follows; the reverse (II) does not."},{"id":55,"question_text":"Verbal Intelligence: Statements: Some pens are books. All books are tables. Conclusions: I. Some pens are tables. II. All tables are books.","option_a":"Only conclusion II follows","option_b":"Both conclusions follow","option_c":"Only conclusion I follows","option_d":"Neither conclusion follows","section":"Verbal Intelligence","correct_option":"C","difficulty":"Medium","explanation":"Only conclusion I follows. The pens that are books are also tables, so I follows. Not every table need be a book, so II does not."},{"id":56,"question_text":"Verbal Intelligence: Statements: All doctors are educated. Some educated persons are rich. Conclusions: I. Some doctors are rich. II. Some rich persons are educated.","option_a":"Only conclusion I follows","option_b":"Only conclusion II follows","option_c":"Both conclusions follow","option_d":"Neither conclusion follows Clock and Calendar","section":"Verbal Intelligence","correct_option":"B","difficulty":"Hard","explanation":"Only conclusion II follows. ''Some educated are rich'' converts to ''some rich are educated'' (II follows). The rich educated persons may not be doctors, so I does not follow."},{"id":57,"question_text":"Verbal Intelligence: What is the angle between the hour hand and the minute hand at 3:00?","option_a":"60°","option_b":"120°","option_c":"90°","option_d":"180°","section":"Verbal Intelligence","correct_option":"C","difficulty":"Easy","explanation":"90°. Each hour mark is 30° apart; at 3:00 the hands are 3 marks apart = 90°."},{"id":58,"question_text":"Verbal Intelligence: What is the angle between the hands of a clock at 4:30?","option_a":"45°","option_b":"30°","option_c":"60°","option_d":"75°","section":"Verbal Intelligence","correct_option":"A","difficulty":"Medium","explanation":"45°. Hour hand = 4×30 + 15 = 135°; minute hand = 180°. Difference = 45°."},{"id":59,"question_text":"Verbal Intelligence: What is the angle between the hour hand and the minute hand at 7:20?","option_a":"100°","option_b":"90°","option_c":"110°","option_d":"120°","section":"Verbal Intelligence","correct_option":"A","difficulty":"Hard","explanation":"100°. Formula |30H − 5.5M| = |210 − 110| = 100°."},{"id":60,"question_text":"Verbal Intelligence: On which day of the week did 14 August 1947 fall?","option_a":"Thursday","option_b":"Wednesday","option_c":"Friday","option_d":"Saturday PATTERNS) (60 questions, 45 min) Each question shows a pattern. Choose the option that completes it (A to D; the odd-one-out questions have A to E).","section":"Verbal Intelligence","correct_option":"A","difficulty":"Medium","explanation":"Thursday. 14 August 1947 was a Thursday (verified from the calendar)."},{"id":61,"question_text":"Non-Verbal Intelligence: Which figure comes next in the series?","option_a":"Figure A","option_b":"Figure B","option_c":"Figure C","option_d":"Figure D","section":"Non-Verbal Intelligence","image_url":"/images/mock-tests/pma-lc159-mock-test-2/q061.png","correct_option":"B","difficulty":"Easy","explanation":"One square is removed each step: 6, 5, 4, 3, 2."},{"id":62,"question_text":"Non-Verbal Intelligence: Which option is the mirror image of the figure on the left of the dotted mirror line?","option_a":"Figure A","option_b":"Figure B","option_c":"Figure C","option_d":"Figure D","section":"Non-Verbal Intelligence","image_url":"/images/mock-tests/pma-lc159-mock-test-2/q062.png","correct_option":"A","difficulty":"Easy","explanation":"A mirror turns left into right (a left-to-right reflection). The arrow''s dot ends up on the opposite side of the shaft and the angle becomes its negative; the choice that is merely turned (rotated) or flipped top-to-bottom is wrong."},{"id":63,"question_text":"Non-Verbal Intelligence: Which figure completes the 3 × 3 matrix (bottom-right cell)?","option_a":"Figure A","option_b":"Figure B","option_c":"Figure C","option_d":"Figure D","section":"Non-Verbal Intelligence","image_url":"/images/mock-tests/pma-lc159-mock-test-2/q063.png","correct_option":"C","difficulty":"Easy","explanation":"Each row and each column contains triangle, square and circle once. The missing figure is the square."},{"id":64,"question_text":"Non-Verbal Intelligence: Which figure comes next in the series?","option_a":"Figure A","option_b":"Figure B","option_c":"Figure C","option_d":"Figure D","section":"Non-Verbal Intelligence","image_url":"/images/mock-tests/pma-lc159-mock-test-2/q064.png","correct_option":"A","difficulty":"Easy","explanation":"The arrow turns 90° clockwise at every step: 0°, 90°, 180°, 270°, so the next is a full turn back to the start."},{"id":65,"question_text":"Non-Verbal Intelligence: Which figure comes next in the series?","option_a":"Figure A","option_b":"Figure B","option_c":"Figure C","option_d":"Figure D","section":"Non-Verbal Intelligence","image_url":"/images/mock-tests/pma-lc159-mock-test-2/q065.png","correct_option":"D","difficulty":"Easy","explanation":"One more cell is shaded each step, filling in reading order (left to right, top to bottom)."},{"id":66,"question_text":"Non-Verbal Intelligence: Choose the figure that completes the second pair in the same way as the first.","option_a":"Figure A","option_b":"Figure B","option_c":"Figure C","option_d":"Figure D","section":"Non-Verbal Intelligence","image_url":"/images/mock-tests/pma-lc159-mock-test-2/q066.png","correct_option":"B","difficulty":"Easy","explanation":"The shape becomes shaded (same number of sides)."},{"id":67,"question_text":"Non-Verbal Intelligence: Find the odd one out.","option_a":"Figure A","option_b":"Figure B","option_c":"Figure C","option_d":"Figure D","section":"Non-Verbal Intelligence","option_e":"Figure E","image_url":"/images/mock-tests/pma-lc159-mock-test-2/q067.png","correct_option":"C","difficulty":"Easy","explanation":"Four figures are triangles (3 sides); one is a square (4 sides)."},{"id":68,"question_text":"Non-Verbal Intelligence: Which figure comes next in the series?","option_a":"Figure A","option_b":"Figure B","option_c":"Figure C","option_d":"Figure D","section":"Non-Verbal Intelligence","image_url":"/images/mock-tests/pma-lc159-mock-test-2/q068.png","correct_option":"A","difficulty":"Easy","explanation":"The shaded cell moves one place clockwise around the border each step."},{"id":69,"question_text":"Non-Verbal Intelligence: Choose the figure that completes the second pair in the same way as the first.","option_a":"Figure A","option_b":"Figure B","option_c":"Figure C","option_d":"Figure D","section":"Non-Verbal Intelligence","image_url":"/images/mock-tests/pma-lc159-mock-test-2/q069.png","correct_option":"B","difficulty":"Easy","explanation":"The shape gains one side."},{"id":70,"question_text":"Non-Verbal Intelligence: Which figure comes next in the series?","option_a":"Figure A","option_b":"Figure B","option_c":"Figure C","option_d":"Figure D","section":"Non-Verbal Intelligence","image_url":"/images/mock-tests/pma-lc159-mock-test-2/q070.png","correct_option":"B","difficulty":"Easy","explanation":"The shaded cell moves one place anticlockwise around the border each step."},{"id":71,"question_text":"Non-Verbal Intelligence: Which figure comes next in the series?","option_a":"Figure A","option_b":"Figure B","option_c":"Figure C","option_d":"Figure D","section":"Non-Verbal Intelligence","image_url":"/images/mock-tests/pma-lc159-mock-test-2/q071.png","correct_option":"A","difficulty":"Easy","explanation":"Turns 45° clockwise each step; the next position is 180° (pointing down)."},{"id":72,"question_text":"Non-Verbal Intelligence: Which figure comes next in the series?","option_a":"Figure A","option_b":"Figure B","option_c":"Figure C","option_d":"Figure D","section":"Non-Verbal Intelligence","image_url":"/images/mock-tests/pma-lc159-mock-test-2/q072.png","correct_option":"C","difficulty":"Easy","explanation":"The number of sides increases by 1: 3, 4, 5, 6, 7 (heptagon)."},{"id":73,"question_text":"Non-Verbal Intelligence: Which figure comes next in the series?","option_a":"Figure A","option_b":"Figure B","option_c":"Figure C","option_d":"Figure D","section":"Non-Verbal Intelligence","image_url":"/images/mock-tests/pma-lc159-mock-test-2/q073.png","correct_option":"D","difficulty":"Easy","explanation":"The arrow turns 90° anticlockwise each step. After pointing left (180° from start it is pointing down), the next turn returns it to the first position."},{"id":74,"question_text":"Non-Verbal Intelligence: Which figure completes the 3 × 3 matrix (bottom-right cell)?","option_a":"Figure A","option_b":"Figure B","option_c":"Figure C","option_d":"Figure D","section":"Non-Verbal Intelligence","image_url":"/images/mock-tests/pma-lc159-mock-test-2/q074.png","correct_option":"B","difficulty":"Easy","explanation":"Columns give the count (1, 2, 3) and rows give the shape (circles, squares, triangles). Bottom-right = 3 triangles."},{"id":75,"question_text":"Non-Verbal Intelligence: Find the odd one out.","option_a":"Figure A","option_b":"Figure B","option_c":"Figure C","option_d":"Figure D","section":"Non-Verbal Intelligence","option_e":"Figure E","image_url":"/images/mock-tests/pma-lc159-mock-test-2/q075.png","correct_option":"B","difficulty":"Easy","explanation":"Four figures show 3 dots; one shows 4 dots."},{"id":76,"question_text":"Non-Verbal Intelligence: Choose the figure that completes the second pair in the same way as the first.","option_a":"Figure A","option_b":"Figure B","option_c":"Figure C","option_d":"Figure D","section":"Non-Verbal Intelligence","image_url":"/images/mock-tests/pma-lc159-mock-test-2/q076.png","correct_option":"A","difficulty":"Easy","explanation":"The arrow is rotated 90° clockwise. 180° + 90° = 270°."},{"id":77,"question_text":"Non-Verbal Intelligence: Which figure comes next in the series?","option_a":"Figure A","option_b":"Figure B","option_c":"Figure C","option_d":"Figure D","section":"Non-Verbal Intelligence","image_url":"/images/mock-tests/pma-lc159-mock-test-2/q077.png","correct_option":"C","difficulty":"Easy","explanation":"One more circle is added each step: 1, 2, 3, 4, 5."},{"id":78,"question_text":"Non-Verbal Intelligence: Which figure comes next in the series?","option_a":"Figure A","option_b":"Figure B","option_c":"Figure C","option_d":"Figure D","section":"Non-Verbal Intelligence","image_url":"/images/mock-tests/pma-lc159-mock-test-2/q078.png","correct_option":"B","difficulty":"Easy","explanation":"The number of sides decreases by 1: 8, 7, 6, 5, 4."},{"id":79,"question_text":"Non-Verbal Intelligence: Which figure completes the 3 × 3 matrix (bottom-right cell)?","option_a":"Figure A","option_b":"Figure B","option_c":"Figure C","option_d":"Figure D","section":"Non-Verbal Intelligence","image_url":"/images/mock-tests/pma-lc159-mock-test-2/q079.png","correct_option":"D","difficulty":"Medium","explanation":"Each row and column has an empty, a half-shaded and a fully shaded circle. The missing one is half-shaded."},{"id":80,"question_text":"Non-Verbal Intelligence: Which figure comes next in the series?","option_a":"Figure A","option_b":"Figure B","option_c":"Figure C","option_d":"Figure D","section":"Non-Verbal Intelligence","image_url":"/images/mock-tests/pma-lc159-mock-test-2/q080.png","correct_option":"C","difficulty":"Medium","explanation":"The shaded cell moves three places clockwise around the border each step."},{"id":81,"question_text":"Non-Verbal Intelligence: Which figure comes next in the series?","option_a":"Figure A","option_b":"Figure B","option_c":"Figure C","option_d":"Figure D","section":"Non-Verbal Intelligence","image_url":"/images/mock-tests/pma-lc159-mock-test-2/q081.png","correct_option":"D","difficulty":"Medium","explanation":"Turns 45° anticlockwise each step: 45°, 0°, 315°, 270°, 225°."},{"id":82,"question_text":"Non-Verbal Intelligence: Find the odd one out.","option_a":"Figure A","option_b":"Figure B","option_c":"Figure C","option_d":"Figure D","section":"Non-Verbal Intelligence","option_e":"Figure E","image_url":"/images/mock-tests/pma-lc159-mock-test-2/q082.png","correct_option":"E","difficulty":"Medium","explanation":"Four figures have 5 sides (pentagons); one has 6 sides (hexagon). Rotation and size do not matter."},{"id":83,"question_text":"Non-Verbal Intelligence: Which figure comes next in the series?","option_a":"Figure A","option_b":"Figure B","option_c":"Figure C","option_d":"Figure D","section":"Non-Verbal Intelligence","image_url":"/images/mock-tests/pma-lc159-mock-test-2/q083.png","correct_option":"B","difficulty":"Medium","explanation":"Turns 135° clockwise each step: 0, 135, 270, 405 (=45), 540 (=180)."},{"id":84,"question_text":"Non-Verbal Intelligence: Find the odd one out.","option_a":"Figure A","option_b":"Figure B","option_c":"Figure C","option_d":"Figure D","section":"Non-Verbal Intelligence","option_e":"Figure E","image_url":"/images/mock-tests/pma-lc159-mock-test-2/q084.png","correct_option":"D","difficulty":"Medium","explanation":"Four figures have two shaded quarters side by side (rotations of each other); one has the two shaded quarters diagonally opposite."},{"id":85,"question_text":"Non-Verbal Intelligence: Choose the figure that completes the second pair in the same way as the first.","option_a":"Figure A","option_b":"Figure B","option_c":"Figure C","option_d":"Figure D","section":"Non-Verbal Intelligence","image_url":"/images/mock-tests/pma-lc159-mock-test-2/q085.png","correct_option":"C","difficulty":"Medium","explanation":"Two dots are removed."},{"id":86,"question_text":"Non-Verbal Intelligence: Which figure comes next in the series?","option_a":"Figure A","option_b":"Figure B","option_c":"Figure C","option_d":"Figure D","section":"Non-Verbal Intelligence","image_url":"/images/mock-tests/pma-lc159-mock-test-2/q086.png","correct_option":"B","difficulty":"Medium","explanation":"Two things change together: the arrow turns 90° clockwise and the figure is mirrored on alternate steps. Step 5 is a full turn (back to 0°) and an unmirrored copy (steps 1,3,5 are unmirrored)."},{"id":87,"question_text":"Non-Verbal Intelligence: Which figure completes the 3 × 3 matrix (bottom-right cell)?","option_a":"Figure A","option_b":"Figure B","option_c":"Figure C","option_d":"Figure D","section":"Non-Verbal Intelligence","image_url":"/images/mock-tests/pma-lc159-mock-test-2/q087.png","correct_option":"B","difficulty":"Medium","explanation":"The arrow angle equals 90° × (row + column). Bottom-right: 90 × 4 = 360° = 0°."},{"id":88,"question_text":"Non-Verbal Intelligence: Choose the figure that completes the second pair in the same way as the first.","option_a":"Figure A","option_b":"Figure B","option_c":"Figure C","option_d":"Figure D","section":"Non-Verbal Intelligence","image_url":"/images/mock-tests/pma-lc159-mock-test-2/q088.png","correct_option":"A","difficulty":"Medium","explanation":"The whole figure is reflected left-to-right. Pointing up stays up but the dot switches side; pointing right becomes pointing left with the dot switched."},{"id":89,"question_text":"Non-Verbal Intelligence: Choose the figure that completes the second pair in the same way as the first.","option_a":"Figure A","option_b":"Figure B","option_c":"Figure C","option_d":"Figure D","section":"Non-Verbal Intelligence","image_url":"/images/mock-tests/pma-lc159-mock-test-2/q089.png","correct_option":"D","difficulty":"Medium","explanation":"The arrow is turned through 180°."},{"id":90,"question_text":"Non-Verbal Intelligence: Find the odd one out.","option_a":"Figure A","option_b":"Figure B","option_c":"Figure C","option_d":"Figure D","section":"Non-Verbal Intelligence","option_e":"Figure E","image_url":"/images/mock-tests/pma-lc159-mock-test-2/q090.png","correct_option":"A","difficulty":"Medium","explanation":"Four figures are made of squares; one is made of triangles."},{"id":91,"question_text":"Non-Verbal Intelligence: Which figure comes next in the series?","option_a":"Figure A","option_b":"Figure B","option_c":"Figure C","option_d":"Figure D","section":"Non-Verbal Intelligence","image_url":"/images/mock-tests/pma-lc159-mock-test-2/q091.png","correct_option":"B","difficulty":"Medium","explanation":"The count stays at 3 while the shape cycles circle, square, triangle. After circle comes square."},{"id":92,"question_text":"Non-Verbal Intelligence: Find the odd one out.","option_a":"Figure A","option_b":"Figure B","option_c":"Figure C","option_d":"Figure D","section":"Non-Verbal Intelligence","option_e":"Figure E","image_url":"/images/mock-tests/pma-lc159-mock-test-2/q092.png","correct_option":"B","difficulty":"Medium","explanation":"Four figures are the same arrow turned to different angles (rotations). One is a mirror image (the dot is on the other side of the arrow), so it can never be matched by turning."},{"id":93,"question_text":"Non-Verbal Intelligence: Which figure comes next in the series?","option_a":"Figure A","option_b":"Figure B","option_c":"Figure C","option_d":"Figure D","section":"Non-Verbal Intelligence","image_url":"/images/mock-tests/pma-lc159-mock-test-2/q093.png","correct_option":"D","difficulty":"Medium","explanation":"The shaded cell jumps two places clockwise around the border each step."},{"id":94,"question_text":"Non-Verbal Intelligence: Which figure comes next in the series?","option_a":"Figure A","option_b":"Figure B","option_c":"Figure C","option_d":"Figure D","section":"Non-Verbal Intelligence","image_url":"/images/mock-tests/pma-lc159-mock-test-2/q094.png","correct_option":"C","difficulty":"Medium","explanation":"Sides go up by 1 and shading alternates (filled, empty, filled, empty). Step 5 is a filled 7-sided figure."},{"id":95,"question_text":"Non-Verbal Intelligence: Which option is the mirror image of the figure on the left of the dotted mirror line?","option_a":"Figure A","option_b":"Figure B","option_c":"Figure C","option_d":"Figure D","section":"Non-Verbal Intelligence","image_url":"/images/mock-tests/pma-lc159-mock-test-2/q095.png","correct_option":"D","difficulty":"Medium","explanation":"A mirror turns left into right (a left-to-right reflection). The arrow''s dot ends up on the opposite side of the shaft and the angle becomes its negative; the choice that is merely turned (rotated) or flipped top-to-bottom is wrong."},{"id":96,"question_text":"Non-Verbal Intelligence: Which figure completes the 3 × 3 matrix (bottom-right cell)?","option_a":"Figure A","option_b":"Figure B","option_c":"Figure C","option_d":"Figure D","section":"Non-Verbal Intelligence","image_url":"/images/mock-tests/pma-lc159-mock-test-2/q096.png","correct_option":"D","difficulty":"Medium","explanation":"In every row, the first number of dots plus the second equals the third (1+2=3, 2+2=4, 3+1=4)."},{"id":97,"question_text":"Non-Verbal Intelligence: Choose the figure that completes the second pair in the same way as the first.","option_a":"Figure A","option_b":"Figure B","option_c":"Figure C","option_d":"Figure D","section":"Non-Verbal Intelligence","image_url":"/images/mock-tests/pma-lc159-mock-test-2/q097.png","correct_option":"A","difficulty":"Medium","explanation":"Circles are replaced by squares; the count stays the same."},{"id":98,"question_text":"Non-Verbal Intelligence: Which option is the mirror image of the figure on the left of the dotted mirror line?","option_a":"Figure A","option_b":"Figure B","option_c":"Figure C","option_d":"Figure D","section":"Non-Verbal Intelligence","image_url":"/images/mock-tests/pma-lc159-mock-test-2/q098.png","correct_option":"B","difficulty":"Medium","explanation":"A mirror turns left into right (a left-to-right reflection). The arrow''s dot ends up on the opposite side of the shaft and the angle becomes its negative; the choice that is merely turned (rotated) or flipped top-to-bottom is wrong."},{"id":99,"question_text":"Non-Verbal Intelligence: Which figure comes next in the series?","option_a":"Figure A","option_b":"Figure B","option_c":"Figure C","option_d":"Figure D","section":"Non-Verbal Intelligence","image_url":"/images/mock-tests/pma-lc159-mock-test-2/q099.png","correct_option":"D","difficulty":"Medium","explanation":"Count rises by 1 and the shape alternates circle, square, circle, square. Step 5 is 5 circles."},{"id":100,"question_text":"Non-Verbal Intelligence: Choose the figure that completes the second pair in the same way as the first.","option_a":"Figure A","option_b":"Figure B","option_c":"Figure C","option_d":"Figure D","section":"Non-Verbal Intelligence","image_url":"/images/mock-tests/pma-lc159-mock-test-2/q100.png","correct_option":"B","difficulty":"Medium","explanation":"Two changes: one more side AND the shading is reversed (filled becomes empty)."},{"id":101,"question_text":"Non-Verbal Intelligence: Which figure completes the 3 × 3 matrix (bottom-right cell)?","option_a":"Figure A","option_b":"Figure B","option_c":"Figure C","option_d":"Figure D","section":"Non-Verbal Intelligence","image_url":"/images/mock-tests/pma-lc159-mock-test-2/q101.png","correct_option":"A","difficulty":"Medium","explanation":"Sides = 3 + row + column, so the bottom-right figure has 7 sides."},{"id":102,"question_text":"Non-Verbal Intelligence: Which figure comes next in the series?","option_a":"Figure A","option_b":"Figure B","option_c":"Figure C","option_d":"Figure D","section":"Non-Verbal Intelligence","image_url":"/images/mock-tests/pma-lc159-mock-test-2/q102.png","correct_option":"D","difficulty":"Hard","explanation":"One more cell is shaded each step, spiralling clockwise around the border (top row, right column, ...)."},{"id":103,"question_text":"Non-Verbal Intelligence: Which figure comes next in the series?","option_a":"Figure A","option_b":"Figure B","option_c":"Figure C","option_d":"Figure D","section":"Non-Verbal Intelligence","image_url":"/images/mock-tests/pma-lc159-mock-test-2/q103.png","correct_option":"B","difficulty":"Hard","explanation":"Two shaded cells both move one place clockwise around the border each step, always staying 3 places apart."},{"id":104,"question_text":"Non-Verbal Intelligence: Which figure comes next in the series?","option_a":"Figure A","option_b":"Figure B","option_c":"Figure C","option_d":"Figure D","section":"Non-Verbal Intelligence","image_url":"/images/mock-tests/pma-lc159-mock-test-2/q104.png","correct_option":"C","difficulty":"Hard","explanation":"Two interleaved series: positions 1,3,5 give 3, 4, 5 and positions 2,4,6 give 5, 6, 7. The 6th figure has 7 sides."},{"id":105,"question_text":"Non-Verbal Intelligence: Which figure comes next in the series?","option_a":"Figure A","option_b":"Figure B","option_c":"Figure C","option_d":"Figure D","section":"Non-Verbal Intelligence","image_url":"/images/mock-tests/pma-lc159-mock-test-2/q105.png","correct_option":"C","difficulty":"Hard","explanation":"Turns alternate +45° and +135°: 0, 45, 180, 225, then +135° gives 360° = 0°."},{"id":106,"question_text":"Non-Verbal Intelligence: Which figure comes next in the series?","option_a":"Figure A","option_b":"Figure B","option_c":"Figure C","option_d":"Figure D","section":"Non-Verbal Intelligence","image_url":"/images/mock-tests/pma-lc159-mock-test-2/q106.png","correct_option":"A","difficulty":"Hard","explanation":"The arrow turns 90° anticlockwise each step while the mirroring alternates. Step 5 is an unmirrored figure (steps 1,3,5) at 45°."},{"id":107,"question_text":"Non-Verbal Intelligence: Choose the figure that completes the second pair in the same way as the first.","option_a":"Figure A","option_b":"Figure B","option_c":"Figure C","option_d":"Figure D","section":"Non-Verbal Intelligence","image_url":"/images/mock-tests/pma-lc159-mock-test-2/q107.png","correct_option":"C","difficulty":"Hard","explanation":"The number of sides is doubled: 3 → 6, so 4 → 8."},{"id":108,"question_text":"Non-Verbal Intelligence: Which figure comes next in the series?","option_a":"Figure A","option_b":"Figure B","option_c":"Figure C","option_d":"Figure D","section":"Non-Verbal Intelligence","image_url":"/images/mock-tests/pma-lc159-mock-test-2/q108.png","correct_option":"C","difficulty":"Hard","explanation":"The turn grows each time: +45°, +90°, +135°, so the next turn is +180°. 270 + 180 = 450 = 90°."},{"id":109,"question_text":"Non-Verbal Intelligence: Which figure comes next in the series?","option_a":"Figure A","option_b":"Figure B","option_c":"Figure C","option_d":"Figure D","section":"Non-Verbal Intelligence","image_url":"/images/mock-tests/pma-lc159-mock-test-2/q109.png","correct_option":"A","difficulty":"Hard","explanation":"The turns alternate: +90°, −45°, +90°, then −45° again. 135 − 45 = 90°."},{"id":110,"question_text":"Non-Verbal Intelligence: Find the odd one out.","option_a":"Figure A","option_b":"Figure B","option_c":"Figure C","option_d":"Figure D","section":"Non-Verbal Intelligence","option_e":"Figure E","image_url":"/images/mock-tests/pma-lc159-mock-test-2/q110.png","correct_option":"D","difficulty":"Hard","explanation":"Check where the dot sits relative to the arrow''s direction: in four figures it is on the right of the shaft when the arrow points up; the odd figure has it on the left (a mirror image)."},{"id":111,"question_text":"Non-Verbal Intelligence: Find the odd one out.","option_a":"Figure A","option_b":"Figure B","option_c":"Figure C","option_d":"Figure D","section":"Non-Verbal Intelligence","option_e":"Figure E","image_url":"/images/mock-tests/pma-lc159-mock-test-2/q111.png","correct_option":"C","difficulty":"Hard","explanation":"Four figures are rotations of the same arrow. One is mirrored (dot on the opposite side of the shaft) and cannot be obtained by rotation."},{"id":112,"question_text":"Non-Verbal Intelligence: Find the odd one out.","option_a":"Figure A","option_b":"Figure B","option_c":"Figure C","option_d":"Figure D","section":"Non-Verbal Intelligence","option_e":"Figure E","image_url":"/images/mock-tests/pma-lc159-mock-test-2/q112.png","correct_option":"A","difficulty":"Hard","explanation":"Four are rotations of the same arrow with its dot on one fixed side; the odd one is a reflection with the dot on the other side."},{"id":113,"question_text":"Non-Verbal Intelligence: Which figure completes the 3 × 3 matrix (bottom-right cell)?","option_a":"Figure A","option_b":"Figure B","option_c":"Figure C","option_d":"Figure D","section":"Non-Verbal Intelligence","image_url":"/images/mock-tests/pma-lc159-mock-test-2/q113.png","correct_option":"D","difficulty":"Hard","explanation":"Columns turn the arrow by 0°, 90°, 180°; rows alternate normal, mirrored, normal. The missing cell is the normal arrow at 180°."},{"id":114,"question_text":"Non-Verbal Intelligence: Which option is the mirror image of the figure on the left of the dotted mirror line?","option_a":"Figure A","option_b":"Figure B","option_c":"Figure C","option_d":"Figure D","section":"Non-Verbal Intelligence","image_url":"/images/mock-tests/pma-lc159-mock-test-2/q114.png","correct_option":"A","difficulty":"Hard","explanation":"A mirror turns left into right (a left-to-right reflection). The arrow''s dot ends up on the opposite side of the shaft and the angle becomes its negative; the choice that is merely turned (rotated) or flipped top-to-bottom is wrong."},{"id":115,"question_text":"Non-Verbal Intelligence: Choose the figure that completes the second pair in the same way as the first.","option_a":"Figure A","option_b":"Figure B","option_c":"Figure C","option_d":"Figure D","section":"Non-Verbal Intelligence","image_url":"/images/mock-tests/pma-lc159-mock-test-2/q115.png","correct_option":"A","difficulty":"Hard","explanation":"Rule: turn 90° clockwise, then reflect left-to-right. For the first pair this gives a pointer at 270° with the dot switched. Applying it to the 45° arrow: 45+90 = 135°, then mirrored = 225° with dot switched."},{"id":116,"question_text":"Non-Verbal Intelligence: Which figure comes next in the series?","option_a":"Figure A","option_b":"Figure B","option_c":"Figure C","option_d":"Figure D","section":"Non-Verbal Intelligence","image_url":"/images/mock-tests/pma-lc159-mock-test-2/q116.png","correct_option":"A","difficulty":"Hard","explanation":"The shaded cell moves three places anticlockwise around the border each step."},{"id":117,"question_text":"Non-Verbal Intelligence: Which figure comes next in the series?","option_a":"Figure A","option_b":"Figure B","option_c":"Figure C","option_d":"Figure D","section":"Non-Verbal Intelligence","image_url":"/images/mock-tests/pma-lc159-mock-test-2/q117.png","correct_option":"D","difficulty":"Hard","explanation":"Count +1 each step and shape cycles circle, square, triangle. Step 5 = 5 squares."},{"id":118,"question_text":"Non-Verbal Intelligence: Which figure completes the 3 × 3 matrix (bottom-right cell)?","option_a":"Figure A","option_b":"Figure B","option_c":"Figure C","option_d":"Figure D","section":"Non-Verbal Intelligence","image_url":"/images/mock-tests/pma-lc159-mock-test-2/q118.png","correct_option":"C","difficulty":"Hard","explanation":"The shaded quarter moves clockwise one place per step along rows and down columns (TL, TR, BR, BL, TL ...). Bottom-right is (2+2) mod 4 = 0, i.e. top-left."},{"id":119,"question_text":"Non-Verbal Intelligence: Find the odd one out.","option_a":"Figure A","option_b":"Figure B","option_c":"Figure C","option_d":"Figure D","section":"Non-Verbal Intelligence","option_e":"Figure E","image_url":"/images/mock-tests/pma-lc159-mock-test-2/q119.png","correct_option":"E","difficulty":"Hard","explanation":"Four filled hexagons (6 sides) and one filled 7-sided figure. Count the corners, ignore size and rotation."},{"id":120,"question_text":"Non-Verbal Intelligence: Which figure comes next in the series?","option_a":"Figure A","option_b":"Figure B","option_c":"Figure C","option_d":"Figure D","section":"Non-Verbal Intelligence","image_url":"/images/mock-tests/pma-lc159-mock-test-2/q120.png","correct_option":"C","difficulty":"Hard","explanation":"Two interleaved series: positions 1,3,5 give 1, 2, 3 and positions 2,4,6 give 3, 4, 5. The 6th figure has 5 circles."},{"id":121,"question_text":"Mathematics: What is 15% of 240?","option_a":"36","option_b":"30","option_c":"32","option_d":"40","section":"Mathematics","correct_option":"A","difficulty":"Easy","explanation":"36. 15% of 240 = 0.15 × 240 = 36."},{"id":122,"question_text":"Mathematics: Solve for x: 5x − 7 = 18","option_a":"x = 5","option_b":"x = 4","option_c":"x = 6","option_d":"x = 3","section":"Mathematics","correct_option":"A","difficulty":"Easy","explanation":"x = 5. 5x = 25, so x = 5."},{"id":123,"question_text":"Mathematics: The L.C.M. of 15, 20 and 30 is","option_a":"30","option_b":"90","option_c":"60","option_d":"120","section":"Mathematics","correct_option":"C","difficulty":"Easy","explanation":"60. 15 = 3×5, 20 = 2²×5, 30 = 2×3×5. LCM = 2²×3×5 = 60."},{"id":124,"question_text":"Mathematics: The average of 6 numbers is 15. When a seventh number is added, the average becomes 16. The seventh number is","option_a":"22","option_b":"16","option_c":"21","option_d":"23","section":"Mathematics","correct_option":"A","difficulty":"Medium","explanation":"22. New total = 7×16 = 112; old total = 6×15 = 90. Seventh number = 112 − 90 = 22."},{"id":125,"question_text":"Mathematics: The two perpendicular sides of a right-angled triangle are 20 cm and 21 cm. The hypotenuse is","option_a":"27 cm","option_b":"31 cm","option_c":"41 cm","option_d":"29 cm","section":"Mathematics","correct_option":"D","difficulty":"Medium","explanation":"29 cm. 400 + 441 = 841 = 29². (20-21-29 is a Pythagorean triple.)"},{"id":126,"question_text":"Mathematics: The compound interest on Rs. 10,000 at 10% per annum for 2 years (compounded annually) is","option_a":"Rs. 2,000","option_b":"Rs. 2,100","option_c":"Rs. 2,200","option_d":"Rs. 1,000","section":"Mathematics","correct_option":"B","difficulty":"Medium","explanation":"Rs. 2,100. Amount = 10000 × 1.1² = 12,100. Interest = 2,100. (Simple interest would be 2,000.)"},{"id":127,"question_text":"Mathematics: A can finish a work in 12 days and B in 18 days. Working together they finish it in","option_a":"7 days","option_b":"7.2 days","option_c":"8 days","option_d":"15 days","section":"Mathematics","correct_option":"B","difficulty":"Hard","explanation":"7.2 days. Together in one day: 1/12 + 1/18 = 5/36. Time = 36/5 = 7.2 days."},{"id":128,"question_text":"Mathematics: A train 120 m long crosses a pole in 6 seconds. Its speed in km/h is","option_a":"20 km/h","option_b":"60 km/h","option_c":"80 km/h","option_d":"72 km/h","section":"Mathematics","correct_option":"D","difficulty":"Hard","explanation":"72 km/h. Speed = 120/6 = 20 m/s = 20 × 3.6 = 72 km/h."},{"id":129,"question_text":"Mathematics: If α and β are the roots of x² − 5x + 6 = 0, then α² + β² =","option_a":"11","option_b":"13","option_c":"25","option_d":"37","section":"Mathematics","correct_option":"B","difficulty":"Hard","explanation":"13. α+β = 5, αβ = 6. α²+β² = (α+β)² − 2αβ = 25 − 12 = 13. (Roots are 2 and 3: 4 + 9 = 13.)"},{"id":130,"question_text":"Mathematics: Two cards are drawn without replacement from a standard deck of 52 cards. The probability that both are aces is","option_a":"1/169","option_b":"1/13","option_c":"1/221","option_d":"1/26","section":"Mathematics","correct_option":"C","difficulty":"Hard","explanation":"1/221. P = (4/52) × (3/51) = 12/2652 = 1/221. (1/169 would be with replacement.)"},{"id":131,"question_text":"Pakistan Studies: Quaid-e-Azam Muhammad Ali Jinnah was born in","option_a":"Lahore","option_b":"Delhi","option_c":"Bombay","option_d":"Karachi","section":"Pakistan Studies","correct_option":"D","difficulty":"Easy","explanation":"Karachi. Jinnah was born on 25 December 1876 in Karachi (Wazir Mansion)."},{"id":132,"question_text":"Pakistan Studies: The All-India Muslim League was founded in 1906 at","option_a":"Lahore","option_b":"Dhaka","option_c":"Lucknow","option_d":"Karachi","section":"Pakistan Studies","correct_option":"B","difficulty":"Easy","explanation":"Dhaka. Founded on 30 December 1906 at Dhaka during the Muhammadan Educational Conference, with Nawab Salimullah Khan as a leading figure."},{"id":133,"question_text":"Pakistan Studies: The height of K2, the highest peak of Pakistan, is about","option_a":"8,849 m","option_b":"8,126 m","option_c":"7,500 m","option_d":"8,611 m","section":"Pakistan Studies","correct_option":"D","difficulty":"Easy","explanation":"8,611 m. K2 is about 8,611 m (second highest in the world). 8,849 m is Everest; 8,126 m is Nanga Parbat."},{"id":134,"question_text":"Pakistan Studies: The Simla Deputation (1906) that met Viceroy Lord Minto was led by","option_a":"Nawab Salimullah","option_b":"Sir Aga Khan III","option_c":"Sir Syed Ahmad Khan","option_d":"M. A. Jinnah","section":"Pakistan Studies","correct_option":"B","difficulty":"Medium","explanation":"Sir Aga Khan III. The deputation of 35 Muslim leaders was led by Sir Aga Khan III."},{"id":135,"question_text":"Pakistan Studies: The Lucknow Pact (1916) was an agreement between National Congress Government Government","option_a":"The Muslim League and the Indian","option_b":"The Muslim League and the British","option_c":"The Congress and the British","option_d":"The Muslim League and the Unionist Party","section":"Pakistan Studies","correct_option":"A","difficulty":"Medium","explanation":"The Muslim League and the Indian National Congress. Congress accepted separate electorates for Muslims; Jinnah played the key role."},{"id":136,"question_text":"Pakistan Studies: The Fourteen Points of Quaid-e-Azam were presented in","option_a":"1927","option_b":"1928","option_c":"1930","option_d":"1929","section":"Pakistan Studies","correct_option":"D","difficulty":"Medium","explanation":"1929. Announced in March 1929 as a reply to the Nehru Report (1928)."},{"id":137,"question_text":"Pakistan Studies: The Allahabad Address (1930) was delivered by","option_a":"M. A. Jinnah","option_b":"Chaudhry Rahmat Ali","option_c":"Allama Muhammad Iqbal","option_d":"Liaquat Ali Khan","section":"Pakistan Studies","correct_option":"C","difficulty":"Medium","explanation":"Allama Muhammad Iqbal. Iqbal, as President of the Muslim League session at Allahabad (December 1930), proposed a consolidated Muslim state in north-west India."},{"id":138,"question_text":"Pakistan Studies: The Nehru Report was published in","option_a":"1927","option_b":"1928","option_c":"1929","option_d":"1930","section":"Pakistan Studies","correct_option":"B","difficulty":"Medium","explanation":"1928. The Nehru Report (August 1928) rejected separate electorates; Jinnah''s Fourteen Points answered it."},{"id":139,"question_text":"Pakistan Studies: The Muslim League observed the ''Day of Deliverance'' on","option_a":"22 December 1939","option_b":"23 March 1940","option_c":"14 August 1947","option_d":"3 June 1947","section":"Pakistan Studies","correct_option":"A","difficulty":"Medium","explanation":"22 December 1939. It was observed to mark the end of Congress ministries, which had resigned in 1939."},{"id":140,"question_text":"Pakistan Studies: The Cripps Mission came to India in","option_a":"1942","option_b":"1940","option_c":"1945","option_d":"1946","section":"Pakistan Studies","correct_option":"A","difficulty":"Hard","explanation":"1942. Sir Stafford Cripps came in March 1942; the Cabinet Mission followed in 1946."},{"id":141,"question_text":"Pakistan Studies: The Boundary Commission of 1947 was headed by","option_a":"Lord Mountbatten","option_b":"Lord Wavell","option_c":"Sir Cyril Radcliffe","option_d":"Sir Stafford Cripps","section":"Pakistan Studies","correct_option":"C","difficulty":"Hard","explanation":"Sir Cyril Radcliffe. Sir Cyril Radcliffe chaired the Punjab and Bengal Boundary Commissions (the Radcliffe Award)."},{"id":142,"question_text":"Pakistan Studies: The plan announced on 3 June 1947 is also known as the","option_a":"Cripps Plan","option_b":"Wavell Plan","option_c":"Mountbatten Plan","option_d":"Cabinet Mission Plan","section":"Pakistan Studies","correct_option":"C","difficulty":"Hard","explanation":"Mountbatten Plan. Lord Mountbatten announced the partition plan on 3 June 1947."},{"id":143,"question_text":"Pakistan Studies: The Objectives Resolution (1949) was moved in the Constituent Assembly by","option_a":"M. A. Jinnah","option_b":"Khawaja Nazimuddin","option_c":"Liaquat Ali Khan","option_d":"Iskander Mirza","section":"Pakistan Studies","correct_option":"C","difficulty":"Medium","explanation":"Liaquat Ali Khan. Prime Minister Liaquat Ali Khan moved it; it was passed on 12 March 1949."},{"id":144,"question_text":"Pakistan Studies: The first constitution of Pakistan came into force on","option_a":"23 March 1956","option_b":"14 August 1947","option_c":"8 June 1962","option_d":"14 August 1973","section":"Pakistan Studies","correct_option":"A","difficulty":"Medium","explanation":"23 March 1956. The 1956 Constitution declared Pakistan an Islamic Republic. 8 June 1962 is the Ayub-era constitution."},{"id":145,"question_text":"Pakistan Studies: The present Constitution of Pakistan was enforced on","option_a":"10 April 1973","option_b":"14 August 1973","option_c":"23 March 1973","option_d":"5 July 1977","section":"Pakistan Studies","correct_option":"B","difficulty":"Hard","explanation":"14 August 1973. It was passed by the National Assembly on 10 April 1973 and enforced on 14 August 1973."},{"id":146,"question_text":"Pakistan Studies: Under the Indus Waters Treaty (1960), the three eastern rivers (Ravi, Beas, Sutlej) were allocated to","option_a":"Pakistan","option_b":"India","option_c":"Both equally","option_d":"The World Bank","section":"Pakistan Studies","correct_option":"B","difficulty":"Hard","explanation":"India. The three western rivers (Indus, Jhelum, Chenab) went to Pakistan; the eastern rivers to India."},{"id":147,"question_text":"Pakistan Studies: The Tashkent Declaration (1966) was signed by Ayub Khan and","option_a":"Jawaharlal Nehru","option_b":"Indira Gandhi","option_c":"Morarji Desai","option_d":"Lal Bahadur Shastri","section":"Pakistan Studies","correct_option":"D","difficulty":"Hard","explanation":"Lal Bahadur Shastri. Signed on 10 January 1966 after the 1965 war, with Soviet mediation at Tashkent."},{"id":148,"question_text":"Pakistan Studies: The Simla Agreement (1972) was signed by Zulfikar Ali Bhutto and","option_a":"Indira Gandhi","option_b":"Lal Bahadur Shastri","option_c":"Morarji Desai","option_d":"Rajiv Gandhi","section":"Pakistan Studies","correct_option":"A","difficulty":"Hard","explanation":"Indira Gandhi. Signed on 2 July 1972 after the 1971 war."},{"id":149,"question_text":"Pakistan Studies: The Tarbela Dam is built on the river","option_a":"Jhelum","option_b":"Chenab","option_c":"Kabul","option_d":"Indus","section":"Pakistan Studies","correct_option":"D","difficulty":"Medium","explanation":"Indus. Tarbela (KP) is on the Indus; Mangla is on the Jhelum."},{"id":150,"question_text":"Pakistan Studies: The Durand Line Agreement between British India and Afghanistan was signed in","option_a":"1879","option_b":"1905","option_c":"1893","option_d":"1919","section":"Pakistan Studies","correct_option":"C","difficulty":"Hard","explanation":"1893. Signed in 1893 by Sir Mortimer Durand and Amir Abdur Rahman Khan. (1879 = Treaty of Gandamak; 1919 = Rawalpindi.)"},{"id":151,"question_text":"Physics: The SI unit of pressure is","option_a":"Newton","option_b":"Joule","option_c":"Watt","option_d":"Pascal","section":"Physics","correct_option":"D","difficulty":"Easy","explanation":"Pascal. Pressure = force/area; 1 Pa = 1 N/m²."},{"id":152,"question_text":"Physics: A car starts from rest and accelerates uniformly at 5 m/s² for 6 s. Its final speed is","option_a":"25 m/s","option_b":"30 m/s","option_c":"35 m/s","option_d":"11 m/s","section":"Physics","correct_option":"B","difficulty":"Easy","explanation":"30 m/s. v = u + at = 0 + 5×6 = 30 m/s."},{"id":153,"question_text":"Physics: The kinetic energy of a 2 kg body moving at 10 m/s is","option_a":"20 J","option_b":"200 J","option_c":"50 J","option_d":"100 J","section":"Physics","correct_option":"D","difficulty":"Medium","explanation":"100 J. KE = ½mv² = ½ × 2 × 100 = 100 J."},{"id":154,"question_text":"Physics: A conductor carries a current of 3 A when a potential difference of 12 V is applied. Its resistance is","option_a":"36 Ω","option_b":"9 Ω","option_c":"4 Ω","option_d":"0.25 Ω","section":"Physics","correct_option":"C","difficulty":"Medium","explanation":"4 Ω. R = V/I = 12/3 = 4 Ω."},{"id":155,"question_text":"Physics: Resistors of 6 Ω and 3 Ω are connected in parallel. Their equivalent resistance is","option_a":"2 Ω","option_b":"9 Ω","option_c":"4.5 Ω","option_d":"3 Ω","section":"Physics","correct_option":"A","difficulty":"Medium","explanation":"2 Ω. 1/R = 1/6 + 1/3 = 1/2, so R = 2 Ω. (Parallel resistance is always less than the smallest.)"},{"id":156,"question_text":"Physics: A sound wave of frequency 170 Hz travels at 340 m/s. Its wavelength is","option_a":"2 m","option_b":"0.5 m","option_c":"1 m","option_d":"4 m","section":"Physics","correct_option":"A","difficulty":"Medium","explanation":"2 m. λ = v/f = 340/170 = 2 m."},{"id":157,"question_text":"Physics: A force of 500 N acts on an area of 0.25 m². The pressure is","option_a":"125 Pa","option_b":"2000 Pa","option_c":"200 Pa","option_d":"500 Pa","section":"Physics","correct_option":"B","difficulty":"Medium","explanation":"2000 Pa. P = F/A = 500/0.25 = 2000 Pa."},{"id":158,"question_text":"Physics: A stone is dropped from a height of 80 m (take g = 10 m/s²). It reaches the ground in","option_a":"4 s","option_b":"8 s","option_c":"2 s","option_d":"16 s","section":"Physics","correct_option":"A","difficulty":"Hard","explanation":"4 s. h = ½gt² → t = √(2h/g) = √16 = 4 s."},{"id":159,"question_text":"Physics: How much heat is needed to melt 0.5 kg of ice at 0 °C? (Latent heat of fusion = 336,000 J/kg)","option_a":"336,000 J","option_b":"16,800 J","option_c":"168,000 J","option_d":"672,000 J","section":"Physics","correct_option":"C","difficulty":"Hard","explanation":"168,000 J. Q = mL = 0.5 × 336,000 = 168,000 J."},{"id":160,"question_text":"Physics: A transformer has 100 turns in the primary and 500 turns in the secondary. If the primary voltage is 220 V, the secondary voltage is","option_a":"44 V","option_b":"1100 V","option_c":"2200 V","option_d":"110 V","section":"Physics","correct_option":"B","difficulty":"Hard","explanation":"1100 V. Vs/Vp = Ns/Np → Vs = 220 × 500/100 = 1100 V (a step-up transformer)."},{"id":161,"question_text":"English: Choose the word closest in meaning to CANDID.","option_a":"Frank","option_b":"Secretive","option_c":"Rude","option_d":"Shy","section":"English","correct_option":"A","difficulty":"Easy","explanation":"Frank. Candid = honest and straightforward."},{"id":162,"question_text":"English: Choose the word closest in meaning to OBSTINATE.","option_a":"Flexible","option_b":"Gentle","option_c":"Timid","option_d":"Stubborn","section":"English","correct_option":"D","difficulty":"Easy","explanation":"Stubborn. Obstinate = refusing to change one''s opinion; stubborn."},{"id":163,"question_text":"English: Choose the word closest in meaning to ALLEVIATE.","option_a":"Worsen","option_b":"Ignore","option_c":"Increase","option_d":"Relieve","section":"English","correct_option":"D","difficulty":"Easy","explanation":"Relieve. To alleviate pain is to make it less severe."},{"id":164,"question_text":"English: Choose the word closest in meaning to LUCID.","option_a":"Clear","option_b":"Confused","option_c":"Dull","option_d":"Hidden","section":"English","correct_option":"A","difficulty":"Medium","explanation":"Clear. Lucid = clearly expressed and easy to understand."},{"id":165,"question_text":"English: Choose the word closest in meaning to PERNICIOUS.","option_a":"Beneficial","option_b":"Harmful","option_c":"Delicious","option_d":"Rapid","section":"English","correct_option":"B","difficulty":"Medium","explanation":"Harmful. Pernicious = having a harmful effect, often gradually."},{"id":166,"question_text":"English: Choose the word closest in meaning to ENIGMA.","option_a":"Solution","option_b":"Puzzle","option_c":"Story","option_d":"Enemy","section":"English","correct_option":"B","difficulty":"Medium","explanation":"Puzzle. An enigma is a mystery or puzzling person or thing."},{"id":167,"question_text":"English: Choose the word closest in meaning to OBSEQUIOUS.","option_a":"Obstinate","option_b":"Obvious","option_c":"Independent","option_d":"Servile","section":"English","correct_option":"D","difficulty":"Hard","explanation":"Servile. Obsequious = excessively eager to please or obey; servile, fawning."},{"id":168,"question_text":"English: Choose the word opposite in meaning to ANCIENT.","option_a":"Old","option_b":"Historic","option_c":"Antique","option_d":"Modern","section":"English","correct_option":"D","difficulty":"Easy","explanation":"Modern. Ancient (very old) is opposite to modern."},{"id":169,"question_text":"English: Choose the word opposite in meaning to DILIGENT.","option_a":"Hardworking","option_b":"Careful","option_c":"Lazy","option_d":"Active","section":"English","correct_option":"C","difficulty":"Easy","explanation":"Lazy. Diligent = hardworking; its opposite is lazy (indolent)."},{"id":170,"question_text":"English: Choose the word opposite in meaning to BENIGN.","option_a":"Kind","option_b":"Malignant","option_c":"Gentle","option_d":"Harmless","section":"English","correct_option":"B","difficulty":"Medium","explanation":"Malignant. Benign (harmless, favourable) is opposite to malignant (harmful, dangerous)."},{"id":171,"question_text":"English: Choose the word opposite in meaning to EXTOL.","option_a":"Praise","option_b":"Glorify","option_c":"Criticize","option_d":"Admire","section":"English","correct_option":"C","difficulty":"Medium","explanation":"Criticize. Extol = praise highly; the opposite is to criticize or condemn."},{"id":172,"question_text":"English: Choose the word opposite in meaning to PARSIMONIOUS.","option_a":"Generous","option_b":"Stingy","option_c":"Thrifty","option_d":"Careful","section":"English","correct_option":"A","difficulty":"Hard","explanation":"Generous. Parsimonious = extremely unwilling to spend; opposite is generous (lavish)."},{"id":173,"question_text":"English: One word for: a person who cannot be corrected.","option_a":"Incorruptible","option_b":"Invincible","option_c":"Incorrigible","option_d":"Illegible","section":"English","correct_option":"C","difficulty":"Medium","explanation":"Incorrigible. Incorrigible = too fixed in bad habits to be reformed. Incorruptible = cannot be bribed."},{"id":174,"question_text":"English: One word for: a speech delivered without preparation.","option_a":"Soliloquy","option_b":"Extempore","option_c":"Monologue","option_d":"Oration","section":"English","correct_option":"B","difficulty":"Medium","explanation":"Extempore. Extempore = spoken or done without preparation. A soliloquy is a speech to oneself."},{"id":175,"question_text":"English: One word for: a place where bees are kept.","option_a":"Aviary","option_b":"Aquarium","option_c":"Apiary","option_d":"Orchard","section":"English","correct_option":"C","difficulty":"Medium","explanation":"Apiary. Apiary = bees; aviary = birds; aquarium = fish."},{"id":176,"question_text":"English: What does the idiom ''to beat about the bush'' mean?","option_a":"To hit a bush","option_b":"To search carefully","option_c":"To speak loudly","option_d":"To avoid coming to the point","section":"English","correct_option":"D","difficulty":"Easy","explanation":"To avoid coming to the point. It means to talk around a subject instead of addressing it directly."},{"id":177,"question_text":"English: What does the idiom ''to hit the nail on the head'' mean?","option_a":"To damage something","option_b":"To work very hard","option_c":"To say or do exactly the right thing","option_d":"To make a mistake","section":"English","correct_option":"C","difficulty":"Easy","explanation":"To say or do exactly the right thing. It means to describe a situation or problem exactly."},{"id":178,"question_text":"English: What does the idiom ''a white elephant'' mean?","option_a":"A costly possession of little use","option_b":"A rare animal","option_c":"A pure-hearted person","option_d":"A very large gift","section":"English","correct_option":"A","difficulty":"Medium","explanation":"A costly possession of little use. A white elephant is something expensive to maintain but useless."},{"id":179,"question_text":"English: What does the idiom ''to smell a rat'' mean?","option_a":"To notice a bad smell","option_b":"To suspect that something is wrong","option_c":"To enjoy a meal","option_d":"To catch a thief","section":"English","correct_option":"B","difficulty":"Medium","explanation":"To suspect that something is wrong. It means to sense that there is trickery or something dishonest."},{"id":180,"question_text":"English: What does the idiom ''to throw in the towel'' mean?","option_a":"To admit defeat and give up","option_b":"To clean up","option_c":"To celebrate","option_d":"To start fighting","section":"English","correct_option":"A","difficulty":"Hard","explanation":"To admit defeat and give up. From boxing: a trainer throws in a towel to stop a fight."},{"id":181,"question_text":"English: Choose the correct option: Each of the students ____ a prize.","option_a":"has received","option_b":"have received","option_c":"were received","option_d":"are receiving","section":"English","correct_option":"A","difficulty":"Easy","explanation":"has received. ''Each'' is singular, so it takes a singular verb: has received."},{"id":182,"question_text":"English: Choose the correct option: He insisted ____ paying the bill.","option_a":"for","option_b":"to","option_c":"on","option_d":"at","section":"English","correct_option":"C","difficulty":"Easy","explanation":"on. Insist on (doing something)."},{"id":183,"question_text":"English: Choose the correct option: Hardly had he arrived ____ it began to rain.","option_a":"than","option_b":"then","option_c":"while","option_d":"when","section":"English","correct_option":"D","difficulty":"Medium","explanation":"when. Hardly/scarcely are followed by ''when''; ''no sooner'' is followed by ''than''."},{"id":184,"question_text":"English: Choose the correct option: I wish I ____ a bird.","option_a":"am","option_b":"were","option_c":"was","option_d":"will be","section":"English","correct_option":"B","difficulty":"Medium","explanation":"were. After ''wish'' (an unreal present wish) the subjunctive ''were'' is used for all persons."},{"id":185,"question_text":"English: Choose the correct option: This is the man ____ I met yesterday.","option_a":"whose","option_b":"whom","option_c":"which","option_d":"what","section":"English","correct_option":"B","difficulty":"Medium","explanation":"whom. ''Whom'' is the object of ''met'' and refers to a person."},{"id":186,"question_text":"English: Choose the correct option: Scarcely had the bell rung ____ the students ran out.","option_a":"than","option_b":"as","option_c":"while","option_d":"when","section":"English","correct_option":"D","difficulty":"Hard","explanation":"when. Scarcely/hardly ... when; no sooner ... than."},{"id":187,"question_text":"English: Choose the correct option: Neither the teacher nor the students ____ present.","option_a":"was","option_b":"were","option_c":"is","option_d":"has been","section":"English","correct_option":"B","difficulty":"Hard","explanation":"were. With ''neither ... nor'' the verb agrees with the nearer subject (''students'', plural): were."},{"id":188,"question_text":"English: Select the correctly spelled word.","option_a":"Embarrassment","option_b":"Embarassment","option_c":"Embarrasment","option_d":"Embaressment","section":"English","correct_option":"A","difficulty":"Medium","explanation":"Embarrassment. Double r and double s: embarrassment."},{"id":189,"question_text":"English: Select the correctly spelled word.","option_a":"Neccessary","option_b":"Necesary","option_c":"Necessary","option_d":"Necessery","section":"English","correct_option":"C","difficulty":"Medium","explanation":"Necessary. One c, two s: necessary (one collar, two sleeves)."},{"id":190,"question_text":"English: Choose the correct passive form of: ''Open the door.''","option_a":"Let the door be opened.","option_b":"The door opens.","option_c":"The door was opened.","option_d":"Open the door be. min)","section":"English","correct_option":"A","difficulty":"Hard","explanation":"Let the door be opened.. Imperative sentences take ''Let ... be + past participle'' in the passive."},{"id":191,"question_text":"General Knowledge: The largest planet in the solar system is","option_a":"Saturn","option_b":"Neptune","option_c":"Jupiter","option_d":"Earth","section":"General Knowledge","correct_option":"C","difficulty":"Easy","explanation":"Jupiter. Jupiter is the largest planet."},{"id":192,"question_text":"General Knowledge: The largest ocean of the world is the","option_a":"Pacific Ocean","option_b":"Atlantic Ocean","option_c":"Indian Ocean","option_d":"Arctic Ocean","section":"General Knowledge","correct_option":"A","difficulty":"Easy","explanation":"Pacific Ocean. The Pacific covers about one-third of the Earth''s surface."},{"id":193,"question_text":"General Knowledge: The chemical symbol of gold is","option_a":"Ag","option_b":"Gd","option_c":"Au","option_d":"Go","section":"General Knowledge","correct_option":"C","difficulty":"Easy","explanation":"Au. Au (from Latin aurum). Ag is silver."},{"id":194,"question_text":"General Knowledge: The smallest country of the world by area is","option_a":"Monaco","option_b":"Malta","option_c":"Vatican City","option_d":"San Marino","section":"General Knowledge","correct_option":"C","difficulty":"Easy","explanation":"Vatican City. Vatican City covers about 0.44 sq km."},{"id":195,"question_text":"General Knowledge: The national animal of Pakistan is the","option_a":"Markhor","option_b":"Snow leopard","option_c":"Indus dolphin","option_d":"Ibex","section":"General Knowledge","correct_option":"A","difficulty":"Easy","explanation":"Markhor. The markhor (a wild goat of the mountains) is Pakistan''s national animal."},{"id":196,"question_text":"General Knowledge: The Pakistan Military Academy (PMA) is located at","option_a":"Rawalpindi","option_b":"Quetta","option_c":"Kohat","option_d":"Kakul (Abbottabad)","section":"General Knowledge","correct_option":"D","difficulty":"Easy","explanation":"Kakul (Abbottabad). PMA Kakul is near Abbottabad, Khyber Pakhtunkhwa."},{"id":197,"question_text":"General Knowledge: Defence Day of Pakistan is observed on","option_a":"14 August","option_b":"6 September","option_c":"23 March","option_d":"11 September","section":"General Knowledge","correct_option":"B","difficulty":"Medium","explanation":"6 September. It commemorates the defence of Pakistan in the 1965 war."},{"id":198,"question_text":"General Knowledge: The first recipient of the Nishan-e-Haider was Shaheed","option_a":"Captain Raja Muhammad Sarwar","option_b":"Major Tufail Muhammad","option_c":"Major Raja Aziz Bhatti","option_d":"Sawar Muhammad Hussain","section":"General Knowledge","correct_option":"A","difficulty":"Medium","explanation":"Captain Raja Muhammad Sarwar Shaheed. Captain Sarwar (Kashmir, 1948) was the first recipient of Pakistan''s highest military gallantry award."},{"id":199,"question_text":"General Knowledge: Youm-e-Takbeer commemorates Pakistan''s nuclear tests at Chagai, conducted on","option_a":"11 May 1998","option_b":"6 September 1965","option_c":"28 May 1999","option_d":"28 May 1998","section":"General Knowledge","correct_option":"D","difficulty":"Medium","explanation":"28 May 1998. Pakistan conducted its nuclear tests at Chagai (Balochistan) on 28 May 1998."},{"id":200,"question_text":"General Knowledge: The United Nations was founded in","option_a":"1945","option_b":"1919","option_c":"1939","option_d":"1948","section":"General Knowledge","correct_option":"A","difficulty":"Medium","explanation":"1945. The UN Charter came into force on 24 October 1945."},{"id":201,"question_text":"General Knowledge: Pakistan became a member of the United Nations on","option_a":"14 August 1947","option_b":"30 September 1947","option_c":"24 October 1945","option_d":"23 March 1956","section":"General Knowledge","correct_option":"B","difficulty":"Medium","explanation":"30 September 1947. Pakistan was admitted to the UN on 30 September 1947."},{"id":202,"question_text":"General Knowledge: The headquarters of the Organization of Islamic Cooperation (OIC) is in","option_a":"Riyadh","option_b":"Cairo","option_c":"Istanbul","option_d":"Jeddah","section":"General Knowledge","correct_option":"D","difficulty":"Medium","explanation":"Jeddah. The OIC Secretariat is in Jeddah, Saudi Arabia."},{"id":203,"question_text":"General Knowledge: The SAARC Secretariat is located in","option_a":"Dhaka","option_b":"Kathmandu","option_c":"New Delhi","option_d":"Colombo","section":"General Knowledge","correct_option":"B","difficulty":"Medium","explanation":"Kathmandu. SAARC''s secretariat is in Kathmandu, Nepal."},{"id":204,"question_text":"General Knowledge: The headquarters of the Economic Cooperation Organization (ECO) is in","option_a":"Ankara","option_b":"Tehran","option_c":"Islamabad","option_d":"Tashkent","section":"General Knowledge","correct_option":"B","difficulty":"Medium","explanation":"Tehran. ECO''s secretariat is in Tehran, Iran."},{"id":205,"question_text":"General Knowledge: The motto of the Pakistan Army is","option_a":"Unity, Faith, Discipline","option_b":"Iman, Taqwa, Jihad fi Sabilillah","option_c":"Allahu Akbar","option_d":"Duty, Honour, Country","section":"General Knowledge","correct_option":"B","difficulty":"Medium","explanation":"Iman, Taqwa, Jihad fi Sabilillah. ''Unity, Faith, Discipline'' is the national motto; the Army''s is Iman, Taqwa, Jihad fi Sabilillah."},{"id":206,"question_text":"General Knowledge: The Strait of Gibraltar separates Spain from","option_a":"Morocco","option_b":"Algeria","option_c":"Portugal","option_d":"Tunisia","section":"General Knowledge","correct_option":"A","difficulty":"Hard","explanation":"Morocco. The strait lies between southern Spain and northern Morocco, linking the Atlantic and the Mediterranean."},{"id":207,"question_text":"General Knowledge: Dr Abdus Salam received the Nobel Prize in Physics in","option_a":"1974","option_b":"1984","option_c":"1979","option_d":"1971","section":"General Knowledge","correct_option":"C","difficulty":"Hard","explanation":"1979. He shared the 1979 Nobel Prize in Physics (electroweak theory)."},{"id":208,"question_text":"General Knowledge: Mount Everest lies on the border of Nepal and","option_a":"India","option_b":"Bhutan","option_c":"China (Tibet)","option_d":"Pakistan","section":"General Knowledge","correct_option":"C","difficulty":"Hard","explanation":"China (Tibet). Everest is on the Nepal-China border."},{"id":209,"question_text":"General Knowledge: NATO was established in","option_a":"1945","option_b":"1955","option_c":"1939","option_d":"1949","section":"General Knowledge","correct_option":"D","difficulty":"Hard","explanation":"1949. The North Atlantic Treaty was signed in April 1949. (1955 = Warsaw Pact.)"},{"id":210,"question_text":"General Knowledge: The largest country of the world by area is","option_a":"Canada","option_b":"China","option_c":"United States","option_d":"Russia","section":"General Knowledge","correct_option":"D","difficulty":"Hard","explanation":"Russia. Russia covers about 17 million sq km."},{"id":211,"question_text":"Islamic Studies: Which Surah of the Holy Quran does NOT begin with Bismillah?","option_a":"At-Tawbah","option_b":"Al-Anfal","option_c":"Yunus","option_d":"Al-Fatiha","section":"Islamic Studies","correct_option":"A","difficulty":"Easy","explanation":"At-Tawbah. Surah At-Tawbah (Bara''at) is the only Surah without Bismillah at its start."},{"id":212,"question_text":"Islamic Studies: About how many Muslims fought in the Battle of Badr?","option_a":"700","option_b":"1,000","option_c":"313","option_d":"3,000","section":"Islamic Studies","correct_option":"C","difficulty":"Easy","explanation":"313. About 313 Muslims faced roughly 1,000 of Quraysh on 17 Ramadan, 2 AH."},{"id":213,"question_text":"Islamic Studies: The Battle of Uhud was fought in","option_a":"3 AH","option_b":"2 AH","option_c":"5 AH","option_d":"6 AH","section":"Islamic Studies","correct_option":"A","difficulty":"Medium","explanation":"3 AH. Badr 2 AH, Uhud 3 AH, Khandaq 5 AH, Hudaybiyyah 6 AH."},{"id":214,"question_text":"Islamic Studies: The idea of digging a trench (Khandaq) was suggested by","option_a":"Hazrat Bilal (RA)","option_b":"Hazrat Salman Farsi (RA)","option_c":"Hazrat Abu Dharr (RA)","option_d":"Hazrat Ali (RA)","section":"Islamic Studies","correct_option":"B","difficulty":"Medium","explanation":"Hazrat Salman Farsi (RA). Salman al-Farsi proposed the trench in the Battle of the Trench (5 AH)."},{"id":215,"question_text":"Islamic Studies: The Treaty of Hudaybiyyah was signed in","option_a":"6 AH","option_b":"5 AH","option_c":"7 AH","option_d":"8 AH","section":"Islamic Studies","correct_option":"A","difficulty":"Medium","explanation":"6 AH. A ten-year truce with Quraysh in 6 AH, called a clear victory in Surah Al-Fath."},{"id":216,"question_text":"Islamic Studies: The expedition of Tabuk took place in","option_a":"8 AH","option_b":"9 AH","option_c":"10 AH","option_d":"7 AH","section":"Islamic Studies","correct_option":"B","difficulty":"Medium","explanation":"9 AH. Tabuk was the last major expedition of the Holy Prophet (PBUH), in 9 AH."},{"id":217,"question_text":"Islamic Studies: Hazrat Umar (RA) was martyred by","option_a":"Abdur Rahman ibn Muljam","option_b":"Abu Lulu Firoz","option_c":"Marwan","option_d":"Walid","section":"Islamic Studies","correct_option":"B","difficulty":"Hard","explanation":"Abu Lulu Firoz. Umar (RA) was stabbed in 23 AH while leading Fajr prayer. Ibn Muljam killed Hazrat Ali (RA)."},{"id":218,"question_text":"Islamic Studies: Hazrat Uthman (RA) was martyred in","option_a":"23 AH","option_b":"36 AH","option_c":"40 AH","option_d":"35 AH","section":"Islamic Studies","correct_option":"D","difficulty":"Hard","explanation":"35 AH. He was martyred in 35 AH (656 CE) in Madinah."},{"id":219,"question_text":"Islamic Studies: Who was appointed by Hazrat Abu Bakr (RA) to head the compilation of the Quran into one volume?","option_a":"Hazrat Abdullah bin Masud (RA)","option_b":"Hazrat Ubayy bin Kab (RA)","option_c":"Hazrat Ali (RA)","option_d":"Hazrat Zaid bin Thabit (RA)","section":"Islamic Studies","correct_option":"D","difficulty":"Hard","explanation":"Hazrat Zaid bin Thabit (RA). After the Battle of Yamamah, Zaid ibn Thabit compiled the Quran. Uthman (RA) later made standard copies."},{"id":220,"question_text":"Islamic Studies: During the Hijrah the Holy Prophet (PBUH) stayed in the Cave of Thawr for about","option_a":"one day","option_b":"seven days","option_c":"three days","option_d":"ten days","section":"Islamic Studies","correct_option":"C","difficulty":"Hard","explanation":"three days. He and Hazrat Abu Bakr (RA) hid in Thawr for about three days before travelling to Madinah."}]'::jsonb),
  ('academic-portion-mock-test-2', '[{"id":1,"question_text":"Synonym: Choose the word closest in meaning to METICULOUS.","option_a":"Careful","option_b":"Hasty","option_c":"Careless","option_d":"Lazy","correct_option":"A","explanation":"Meticulous means showing great attention to detail. ⚡ Trick: Link it with \"minute\" details: a meticulous person checks every minute detail.","section":"English","topic":"Synonym"},{"id":2,"question_text":"Synonym: Choose the word closest in meaning to ARDUOUS.","option_a":"Short","option_b":"Difficult","option_c":"Easy","option_d":"Pleasant","correct_option":"B","explanation":"Arduous describes a task needing great effort and endurance. ⚡ Trick: ARDUOUS sounds like \"hard-uous\", it means HARD.","section":"English","topic":"Synonym"},{"id":3,"question_text":"Synonym: Choose the word closest in meaning to PRUDENT.","option_a":"Foolish","option_b":"Rash","option_c":"Wise and careful","option_d":"Generous","correct_option":"C","explanation":"A prudent person acts with care and good judgement. ⚡ Trick: Prudent ≈ cautious. Opposite: imprudent/rash.","section":"English","topic":"Synonym"},{"id":4,"question_text":"Synonym: Choose the word closest in meaning to AUSTERE.","option_a":"Strict and plain","option_b":"Wealthy","option_c":"Cheerful","option_d":"Luxurious","correct_option":"A","explanation":"Austere means severe in manner, or without luxury. ⚡ Trick: Think of \"austerity measures\": cutting luxuries.","section":"English","topic":"Synonym"},{"id":5,"question_text":"Synonym: Choose the word closest in meaning to TENACIOUS.","option_a":"Persistent","option_b":"Weak","option_c":"Timid","option_d":"Generous","correct_option":"A","explanation":"Tenacious means holding firmly to a purpose; not giving up. ⚡ Trick: Tenacious ← \"tenacity\" ← a tenant holds on to the house. Same idea as \"determined\".","section":"English","topic":"Synonym"},{"id":6,"question_text":"Synonym: Choose the word closest in meaning to AMICABLE.","option_a":"Formal","option_b":"Hostile","option_c":"Friendly","option_d":"Bitter","correct_option":"C","explanation":"Amicable (Latin amicus = friend). ⚡ Trick: Amicable, \"amigo\" and \"amity\" all share the root for FRIEND.","section":"English","topic":"Synonym"},{"id":7,"question_text":"Synonym: Choose the word closest in meaning to FRUGAL.","option_a":"Lavish","option_b":"Thrifty","option_c":"Wealthy","option_d":"Generous","correct_option":"B","explanation":"Frugal means careful about spending money. ⚡ Trick: Frugal ≈ thrifty ≈ economical. Opposite: extravagant.","section":"English","topic":"Synonym"},{"id":8,"question_text":"Synonym: Choose the word closest in meaning to AUDACIOUS.","option_a":"Careful","option_b":"Daring","option_c":"Silent","option_d":"Timid","correct_option":"B","explanation":"Audacious means willing to take bold risks. ⚡ Trick: Audacious ~ \"audacity\" ~ having the nerve.","section":"English","topic":"Synonym"},{"id":9,"question_text":"Antonym: Choose the word opposite in meaning to GENEROUS.","option_a":"Stingy","option_b":"Kind","option_c":"Charitable","option_d":"Liberal","correct_option":"A","explanation":"Generous means giving freely; stingy means unwilling to give. ⚡ Trick: Eliminate the three words that all mean \"giving\"; the odd one out is the answer.","section":"English","topic":"Antonym"},{"id":10,"question_text":"Antonym: Choose the word opposite in meaning to EXPAND.","option_a":"Spread","option_b":"Contract","option_c":"Enlarge","option_d":"Extend","correct_option":"B","explanation":"⚡ Trick: Expand ↔ Contract; Inflate ↔ Deflate; Increase ↔ Decrease.","section":"English","topic":"Antonym"},{"id":11,"question_text":"Antonym: Choose the word opposite in meaning to TRANSPARENT.","option_a":"Clear","option_b":"Opaque","option_c":"Glassy","option_d":"Thin","correct_option":"B","explanation":"A transparent material lets light pass through; an opaque one does not. ⚡ Trick: Transparent ↔ Opaque, with Translucent in between.","section":"English","topic":"Antonym"},{"id":12,"question_text":"Antonym: Choose the word opposite in meaning to ZENITH.","option_a":"Summit","option_b":"Climax","option_c":"Peak","option_d":"Nadir","correct_option":"D","explanation":"Zenith is the highest point; nadir is the lowest. ⚡ Trick: Remember the pair Zenith–Nadir.","section":"English","topic":"Antonym"},{"id":13,"question_text":"Antonym: Choose the word opposite in meaning to ARTIFICIAL.","option_a":"Fake","option_b":"Man-made","option_c":"Synthetic","option_d":"Natural","correct_option":"D","explanation":"Artificial = made by people. ⚡ Trick: Three options are synonyms of the given word, so the remaining one must be the opposite.","section":"English","topic":"Antonym"},{"id":14,"question_text":"Antonym: Choose the word opposite in meaning to VICTORY.","option_a":"Conquest","option_b":"Defeat","option_c":"Success","option_d":"Triumph","correct_option":"B","explanation":"⚡ Trick: Remove the options that mean the same (triumph, success, conquest).","section":"English","topic":"Antonym"},{"id":15,"question_text":"One word: One word for: a person who walks in his sleep.","option_a":"Insomniac","option_b":"Hypnotist","option_c":"Somnambulist","option_d":"Somniloquist","correct_option":"C","explanation":"An insomniac cannot sleep; a somniloquist talks in sleep. ⚡ Trick: Somnus = sleep, ambulare = walk (like \"ambulance\", \"amble\").","section":"English","topic":"One word"},{"id":16,"question_text":"One word: The scientific study of birds is called:","option_a":"Ornithology","option_b":"Entomology","option_c":"Archaeology","option_d":"Etymology","correct_option":"A","explanation":"Entomology = insects; etymology = origin of words; archaeology = ancient remains. ⚡ Trick: Ornis (Greek) = bird. \"ENTomology\" → ANTs (insects).","section":"English","topic":"One word"},{"id":17,"question_text":"One word: One word for: a person who speaks or knows many languages.","option_a":"Orator","option_b":"Monolingual","option_c":"Grammarian","option_d":"Polyglot","correct_option":"D","explanation":"Poly = many, glot = tongue. ⚡ Trick: Poly = many (polygon, polytechnic).","section":"English","topic":"One word"},{"id":18,"question_text":"One word: One word for: the killing of one''s brother.","option_a":"Patricide","option_b":"Fratricide","option_c":"Matricide","option_d":"Homicide","correct_option":"B","explanation":"Frater = brother. Patricide = father, matricide = mother. ⚡ Trick: Pater = father, Mater = mother, Frater = brother, Soror = sister (sororicide).","section":"English","topic":"One word"},{"id":19,"question_text":"Idiom: What does the idiom \"to burn the midnight oil\" mean?","option_a":"To waste fuel","option_b":"To start a fire","option_c":"To work or study late into the night","option_d":"To sleep early","correct_option":"C","explanation":"⚡ Trick: Whenever an idiom contains midnight/late/lamp, think \"working late\".","section":"English","topic":"Idiom"},{"id":20,"question_text":"Idiom: What does the idiom \"to let the cat out of the bag\" mean?","option_a":"To free an animal","option_b":"To lose something valuable","option_c":"To reveal a secret by mistake","option_d":"To make a loud noise","correct_option":"C","explanation":"⚡ Trick: Cat in a bag = hidden secret; let it out = secret revealed.","section":"English","topic":"Idiom"},{"id":21,"question_text":"Idiom: What does the idiom \"once in a blue moon\" mean?","option_a":"At night","option_b":"Every month","option_c":"Very frequently","option_d":"Very rarely","correct_option":"D","explanation":"⚡ Trick: Rare-event idioms: once in a blue moon, a red-letter day.","section":"English","topic":"Idiom"},{"id":22,"question_text":"Idiom: What does the idiom \"to cry over spilt milk\" mean?","option_a":"To waste food","option_b":"To cry loudly","option_c":"To be extremely sad","option_d":"To regret something that cannot be undone","correct_option":"D","explanation":"⚡ Trick: Spilt milk can''t be put back: \"what''s done is done\".","section":"English","topic":"Idiom"},{"id":23,"question_text":"Grammar: He has been working in this office ______ 2015.","option_a":"from","option_b":"for","option_c":"since","option_d":"by","correct_option":"C","explanation":"\"Since\" is used with a fixed point in time; \"for\" with a period. ⚡ Trick: SINCE = Starting point; FOR = Full duration.","section":"English","topic":"Grammar"},{"id":24,"question_text":"Grammar: I look forward to ______ you again.","option_a":"seeing","option_b":"see","option_c":"have seen","option_d":"saw","correct_option":"A","explanation":"In \"look forward to\", \"to\" is a preposition, so it takes a gerund (-ing). ⚡ Trick: Watch for \"to\" + -ing: look forward to, be used to, object to, in addition to.","section":"English","topic":"Grammar"},{"id":25,"question_text":"Grammar: The news ______ true.","option_a":"were","option_b":"have been","option_c":"are","option_d":"is","correct_option":"D","explanation":"\"News\" looks plural but is uncountable (singular). ⚡ Trick: News, information, advice, furniture, luggage, scenery → singular. Also: mathematics, physics, economics.","section":"English","topic":"Grammar"},{"id":26,"question_text":"Grammar: He is senior ______ me.","option_a":"from","option_b":"than","option_c":"to","option_d":"with","correct_option":"C","explanation":"Latin-derived comparatives (senior, junior, superior, inferior, prefer) take \"to\", not \"than\". ⚡ Trick: SIPP words take \"to\": Senior, Inferior, Preferable/Prefer, Prior, Junior, Superior.","section":"English","topic":"Grammar"},{"id":27,"question_text":"Grammar: One of my friends ______ a doctor.","option_a":"were","option_b":"is","option_c":"have been","option_d":"are","correct_option":"B","explanation":"The subject is \"One\" (singular). ⚡ Trick: \"One of + plural noun\" takes a SINGULAR verb. Ignore the words between subject and verb.","section":"English","topic":"Grammar"},{"id":28,"question_text":"Grammar: If he ______ hard, he will pass the examination.","option_a":"will work","option_b":"would work","option_c":"works","option_d":"worked","correct_option":"C","explanation":"First conditional: If + simple present, … will + base verb. ⚡ Trick: Real possibility → If + present, will. Imaginary → If + past, would. Impossible past → If + had, would have.","section":"English","topic":"Grammar"},{"id":29,"question_text":"Grammar: She is the ______ of the two sisters.","option_a":"more tall","option_b":"most tall","option_c":"tallest","option_d":"taller","correct_option":"D","explanation":"Comparing two persons needs the comparative. ⚡ Trick: TWO → comparative (-er); THREE or more → superlative (-est).","section":"English","topic":"Grammar"},{"id":30,"question_text":"Grammar: Many a student ______ failed in this paper.","option_a":"were","option_b":"are","option_c":"has","option_d":"have","correct_option":"C","explanation":"\"Many a + singular noun\" takes a singular verb. ⚡ Trick: \"Many a\" looks plural but behaves SINGULAR; \"many + plural noun\" takes a plural verb.","section":"English","topic":"Grammar"},{"id":31,"question_text":"Correct sentence: Choose the correct sentence.","option_a":"She sings good.","option_b":"She sing well.","option_c":"She singing well.","option_d":"She sings well.","correct_option":"D","explanation":"\"Well\" is the adverb modifying \"sings\". ⚡ Trick: Verb needs an ADVERB (well, quickly); noun needs an ADJECTIVE (good).","section":"English","topic":"Correct sentence"},{"id":32,"question_text":"Correct sentence: Choose the correct sentence.","option_a":"I prefer tea to coffee.","option_b":"I prefer tea over than coffee.","option_c":"I prefer tea from coffee.","option_d":"I prefer tea than coffee.","correct_option":"A","explanation":"⚡ Trick: Prefer … to …; would rather … than ….","section":"English","topic":"Correct sentence"},{"id":33,"question_text":"Correct sentence: Choose the correct sentence.","option_a":"He gave me many advice.","option_b":"He gave me some advice.","option_c":"He gave me an advice.","option_d":"He gave me advices.","correct_option":"B","explanation":"\"Advice\" is uncountable: no \"an\", no plural. ⚡ Trick: Uncountable nouns: advice, information, furniture, luggage, equipment, evidence, knowledge, news.","section":"English","topic":"Correct sentence"},{"id":34,"question_text":"Correct sentence: Choose the correct sentence.","option_a":"The furnitures is old.","option_b":"The furniture is old.","option_c":"The furniture are old.","option_d":"The furnitures are old.","correct_option":"B","explanation":"⚡ Trick: No plural for furniture. Say \"pieces of furniture\".","section":"English","topic":"Correct sentence"},{"id":35,"question_text":"Spelling: Select the correctly spelled word.","option_a":"Seperate","option_b":"Seperete","option_c":"Separete","option_d":"Separate","correct_option":"D","explanation":"⚡ Trick: There''s \"a rat\" in sep-a-rat-e.","section":"English","topic":"Spelling"},{"id":36,"question_text":"Spelling: Select the correctly spelled word.","option_a":"Conscience","option_b":"Conscence","option_c":"Concience","option_d":"Consciense","correct_option":"A","explanation":"⚡ Trick: Remember \"science\" inside \"conscience\".","section":"English","topic":"Spelling"},{"id":37,"question_text":"Preposition: He is afraid ______ snakes.","option_a":"of","option_b":"from","option_c":"with","option_d":"at","correct_option":"A","explanation":"⚡ Trick: Fear words take OF: afraid of, scared of, terrified of, fond of, proud of, jealous of.","section":"English","topic":"Preposition"},{"id":38,"question_text":"Preposition: This book is different ______ that one.","option_a":"from","option_b":"with","option_c":"to","option_d":"than","correct_option":"A","explanation":"⚡ Trick: Different FROM; similar TO; identical WITH.","section":"English","topic":"Preposition"},{"id":39,"question_text":"Voice / Narration: Change into passive voice: \"Who wrote this letter?\"","option_a":"Who was this letter written by?","option_b":"By whom has this letter written?","option_c":"By whom this letter was written?","option_d":"By whom was this letter written?","correct_option":"D","explanation":"Interrogative simple past: Who + wrote + object → By whom + was + object + past participle? ⚡ Trick: \"Who\" → \"By whom\"; helping verb BEFORE the object; verb in 3rd form.","section":"English","topic":"Voice / Narration"},{"id":40,"question_text":"Voice / Narration: Change into indirect speech: She said to me, \"Where are you going?\"","option_a":"She said me where I am going.","option_b":"She asked me where was I going.","option_c":"She asked me where I was going.","option_d":"She told me where am I going.","correct_option":"C","explanation":"\"Said to\" becomes \"asked\"; word order becomes a statement; tense shifts back (are → was). ⚡ Trick: Question → asked; statement word order; no question mark.","section":"English","topic":"Voice / Narration"},{"id":41,"question_text":"Algebra: The sum of the roots of the equation 2x² − 8x + 3 = 0 is:","option_a":"−4","option_b":"3/2","option_c":"8","option_d":"4","correct_option":"D","explanation":"Sum of roots = −b/a = 8/2 = 4. ⚡ Trick: Sum = −b/a, product = c/a. You never need to solve the equation.","section":"Mathematics","topic":"Algebra"},{"id":42,"question_text":"Algebra: The roots of the equation x² − 4x + 4 = 0 are:","option_a":"Real and equal","option_b":"Real and distinct","option_c":"Complex","option_d":"Irrational and distinct","correct_option":"A","explanation":"D = b² − 4ac = 16 − 16 = 0. ⚡ Trick: Spot a perfect square: x² − 4x + 4 = (x − 2)². D > 0 distinct, D = 0 equal, D < 0 complex.","section":"Mathematics","topic":"Algebra"},{"id":43,"question_text":"Sequences: The 5th term of the arithmetic progression 3, 7, 11, … is:","option_a":"15","option_b":"23","option_c":"19","option_d":"20","correct_option":"C","explanation":"aₙ = a + (n − 1)d = 3 + 4 × 4 = 19. ⚡ Trick: To reach the 5th term add the common difference 4 times (not 5).","section":"Mathematics","topic":"Sequences"},{"id":44,"question_text":"Sequences: The sum of the first 10 terms of the series 2 + 4 + 6 + … is:","option_a":"100","option_b":"55","option_c":"120","option_d":"110","correct_option":"D","explanation":"Sₙ = n/2 [2a + (n − 1)d] = 5 [4 + 18] = 110. ⚡ Trick: Sum of first n EVEN numbers = n(n + 1) = 10 × 11 = 110 (first n odd numbers = n²).","section":"Mathematics","topic":"Sequences"},{"id":45,"question_text":"Sequences: The 5th term of the geometric progression 2, 6, 18, … is:","option_a":"162","option_b":"486","option_c":"54","option_d":"90","correct_option":"A","explanation":"r = 3; a₅ = ar⁴ = 2 × 81 = 162. ⚡ Trick: Keep multiplying by 3: 2 → 6 → 18 → 54 → 162.","section":"Mathematics","topic":"Sequences"},{"id":46,"question_text":"Logarithms: The value of log₁₀ 2 + log₁₀ 5 is:","option_a":"1","option_b":"0","option_c":"10","option_d":"7","correct_option":"A","explanation":"log a + log b = log(ab), so log 2 + log 5 = log 10 = 1. ⚡ Trick: Sum of logs = log of product.","section":"Mathematics","topic":"Logarithms"},{"id":47,"question_text":"Trigonometry: If sin θ = 3/5 and θ is acute, then tan θ is:","option_a":"5/3","option_b":"3/4","option_c":"4/5","option_d":"4/3","correct_option":"B","explanation":"Opposite = 3, hypotenuse = 5, adjacent = 4. tan θ = 3/4. ⚡ Trick: Memorise triples 3-4-5, 5-12-13, 8-15-17, 7-24-25.","section":"Mathematics","topic":"Trigonometry"},{"id":48,"question_text":"Mensuration: The area of a circle of radius 7 cm is (π = 22/7):","option_a":"308 cm²","option_b":"154 cm²","option_c":"49 cm²","option_d":"44 cm²","correct_option":"B","explanation":"A = πr² = (22/7) × 49 = 154. (44 cm is the circumference.) ⚡ Trick: When r = 7, area = 22 × 7 = 154; circumference = 2 × 22 = 44.","section":"Mathematics","topic":"Mensuration"},{"id":49,"question_text":"Geometry: The two perpendicular sides of a right-angled triangle are 9 cm and 12 cm. The hypotenuse is:","option_a":"13 cm","option_b":"15 cm","option_c":"21 cm","option_d":"225 cm","correct_option":"B","explanation":"h = √(81 + 144) = √225 = 15. ⚡ Trick: Scale the 3-4-5 triple by 3: 9-12-15.","section":"Mathematics","topic":"Geometry"},{"id":50,"question_text":"Mensuration: The volume of a cylinder of radius 7 cm and height 10 cm is (π = 22/7):","option_a":"440 cm³","option_b":"154 cm³","option_c":"1540 cm³","option_d":"3080 cm³","correct_option":"C","explanation":"V = πr²h = 154 × 10. ⚡ Trick: Volume = base area × height. Base area for r = 7 is 154 (see Q48).","section":"Mathematics","topic":"Mensuration"},{"id":51,"question_text":"Sets: If n(A) = 5, n(B) = 4 and n(A ∩ B) = 2, then n(A ∪ B) is:","option_a":"9","option_b":"11","option_c":"3","option_d":"7","correct_option":"D","explanation":"n(A ∪ B) = 5 + 4 − 2 = 7. ⚡ Trick: Add both sets, then subtract the overlap once.","section":"Mathematics","topic":"Sets"},{"id":52,"question_text":"Algebra: If x + y = 10 and x − y = 2, then x is:","option_a":"4","option_b":"12","option_c":"6","option_d":"8","correct_option":"C","explanation":"Adding the equations: 2x = 12 → x = 6 (y = 4). ⚡ Trick: x = (sum + difference)/2 = 6; y = (sum − difference)/2 = 4.","section":"Mathematics","topic":"Algebra"},{"id":53,"question_text":"Average: The average of five numbers is 20. If one number is removed, the average of the remaining four becomes 18. The removed number is:","option_a":"28","option_b":"22","option_c":"38","option_d":"18","correct_option":"A","explanation":"Total of five = 100; total of four = 72; removed = 28. ⚡ Trick: Convert averages to totals first: removed = old total − new total.","section":"Mathematics","topic":"Average"},{"id":54,"question_text":"Interest: The simple interest on Rs. 2,000 at 5% per annum for 3 years is:","option_a":"Rs. 3,000","option_b":"Rs. 300","option_c":"Rs. 100","option_d":"Rs. 330","correct_option":"B","explanation":"I = PRT/100 = 2000 × 5 × 3/100 = 300. ⚡ Trick: 5% of 2,000 = 100 per year; three years → 300.","section":"Mathematics","topic":"Interest"},{"id":55,"question_text":"Probability: Two dice are thrown together. The probability that the sum of the numbers is 7 is:","option_a":"1/12","option_b":"1/6","option_c":"7/36","option_d":"1/9","correct_option":"B","explanation":"Favourable: (1,6), (2,5), (3,4), (4,3), (5,2), (6,1) = 6 of 36. ⚡ Trick: Seven is the most likely sum of two dice. Sum 2 or 12 → only 1 way each.","section":"Mathematics","topic":"Probability"},{"id":56,"question_text":"Permutation: The value of ⁵P₂ is:","option_a":"25","option_b":"10","option_c":"20","option_d":"120","correct_option":"C","explanation":"⁵P₂ = 5 × 4 = 20. ⚡ Trick: Write r factors starting from n and going down. (⁵C₂ would give 10.)","section":"Mathematics","topic":"Permutation"},{"id":57,"question_text":"Indices: The value of 16^(3/4) is:","option_a":"8","option_b":"12","option_c":"4","option_d":"64","correct_option":"A","explanation":"16^(3/4) = (⁴√16)³ = 2³ = 8. ⚡ Trick: ROOT first (denominator), then POWER (numerator).","section":"Mathematics","topic":"Indices"},{"id":58,"question_text":"Algebra: If x − y = 3 and x² − y² = 15, then x + y is:","option_a":"18","option_b":"12","option_c":"5","option_d":"45","correct_option":"C","explanation":"x² − y² = (x − y)(x + y) → 15 = 3(x + y) → x + y = 5. ⚡ Trick: Whenever x² − y² appears, factorise it first.","section":"Mathematics","topic":"Algebra"},{"id":59,"question_text":"Coordinate Geometry: The distance between the points (1, 2) and (4, 6) is:","option_a":"7","option_b":"25","option_c":"10","option_d":"5","correct_option":"D","explanation":"d = √(3² + 4²) = 5. ⚡ Trick: Differences 3 and 4 → 3-4-5 triangle. (7 is the \"walking\" distance.)","section":"Mathematics","topic":"Coordinate Geometry"},{"id":60,"question_text":"Number Theory: The L.C.M. of 12 and 18 is:","option_a":"216","option_b":"72","option_c":"6","option_d":"36","correct_option":"D","explanation":"12 = 2² × 3; 18 = 2 × 3². LCM = 2² × 3² = 36. ⚡ Trick: LCM = product ÷ HCF = 216 ÷ 6 = 36.","section":"Mathematics","topic":"Number Theory"},{"id":61,"question_text":"Quran: The first revelation to the Holy Prophet (PBUH) was the opening verses of Surah:","option_a":"Al-Fatiha","option_b":"Al-Baqarah","option_c":"Al-Muddaththir","option_d":"Al-Alaq","correct_option":"D","explanation":"First five verses (\"Iqra bismi rabbika…\") came in the Cave of Hira in Ramadan. ⚡ Trick: \"Iqra\" (Read!) was the first word revealed.","section":"Islamiyat","topic":"Quran"},{"id":62,"question_text":"Seerah: The Holy Prophet (PBUH) was born in Makkah in the year known as:","option_a":"The Year of Grief","option_b":"The Year of the Delegations","option_c":"The Year of Hijrah","option_d":"The Year of the Elephant (Aam-ul-Feel)","correct_option":"D","explanation":"Born around 570 CE, the year Abraha''s army attacked the Ka''bah. ⚡ Trick: Surah Al-Feel (105) tells this story.","section":"Islamiyat","topic":"Seerah"},{"id":63,"question_text":"Seerah: The five daily prayers were made obligatory on the occasion of:","option_a":"The Conquest of Makkah","option_b":"Hijrah","option_c":"Mi''raj (the Ascension)","option_d":"The Treaty of Hudaybiyyah","correct_option":"C","explanation":"Salah was prescribed during Isra and Mi''raj, originally 50, reduced to 5. ⚡ Trick: Mi''raj = gift of Salah.","section":"Islamiyat","topic":"Seerah"},{"id":64,"question_text":"Quran: The total number of Surahs in the Holy Quran is:","option_a":"116","option_b":"110","option_c":"120","option_d":"114","correct_option":"D","explanation":"(And 30 Paras/Juz.) ⚡ Trick: Commonly 86 Makki + 28 Madani. First Fatiha, last An-Nas.","section":"Islamiyat","topic":"Quran"},{"id":65,"question_text":"Quran: The longest Surah of the Holy Quran is:","option_a":"Al-Baqarah","option_b":"Al-Kahf","option_c":"Al-Imran","option_d":"An-Nisa","correct_option":"A","explanation":"286 verses. ⚡ Trick: \"Baqarah\" = cow; right after Al-Fatiha and the longest.","section":"Islamiyat","topic":"Quran"},{"id":66,"question_text":"Quran: Which Surah of the Quran does NOT begin with Bismillah?","option_a":"Yunus","option_b":"Al-Anfal","option_c":"Al-Fatiha","option_d":"At-Tawbah","correct_option":"D","explanation":"Also called Bara''at; the only Surah without Bismillah at the start. ⚡ Trick: Tawbah = repentance/warning, no Bismillah.","section":"Islamiyat","topic":"Quran"},{"id":67,"question_text":"Seerah: The number of Muslims who took part in the Battle of Badr was about:","option_a":"100","option_b":"313","option_c":"3000","option_d":"700","correct_option":"B","explanation":"About 313 Muslims faced nearly 1,000 from Quraysh at Badr (17 Ramadan, 2 AH). ⚡ Trick: Badr = 313 vs ~1000. Uhud = 700 vs 3000. Khandaq = 3000 vs 10,000.","section":"Islamiyat","topic":"Seerah"},{"id":68,"question_text":"Seerah: The Treaty of Hudaybiyyah was concluded in:","option_a":"10 A.H.","option_b":"2 A.H.","option_c":"6 A.H.","option_d":"8 A.H.","correct_option":"C","explanation":"A ten-year truce with Quraysh (628 CE), called a \"clear victory\" in Surah Al-Fath. ⚡ Trick: Timeline: Badr 2, Uhud 3, Khandaq 5, Hudaybiyyah 6, Khaybar 7, Fath-e-Makkah 8, Farewell Hajj 10.","section":"Islamiyat","topic":"Seerah"},{"id":69,"question_text":"Seerah: Makkah was conquered peacefully by the Holy Prophet (PBUH) in:","option_a":"6 A.H.","option_b":"10 A.H.","option_c":"8 A.H.","option_d":"7 A.H.","correct_option":"C","explanation":"Ramadan 8 AH (630 CE); a general amnesty was announced. ⚡ Trick: Use the timeline in Q68: Hudaybiyyah (6) → Khaybar (7) → Makkah (8).","section":"Islamiyat","topic":"Seerah"},{"id":70,"question_text":"Seerah: The Farewell Sermon (Khutbah Hajjatul-Wida) was delivered at:","option_a":"Arafat","option_b":"Hira","option_c":"Madinah","option_d":"Mina","correct_option":"A","explanation":"9 Dhul-Hijjah, 10 AH. ⚡ Trick: Day of Arafat = main Hajj day = Farewell Sermon.","section":"Islamiyat","topic":"Seerah"},{"id":71,"question_text":"Caliphs: The Holy Quran was first compiled in one book form during the caliphate of:","option_a":"Hazrat Abu Bakr (RA)","option_b":"Hazrat Ali (RA)","option_c":"Hazrat Uthman (RA)","option_d":"Hazrat Umar (RA)","correct_option":"A","explanation":"After Yamamah, on Umar''s advice, Abu Bakr had Zayd ibn Thabit compile the Quran. Uthman later made standard copies. ⚡ Trick: Abu Bakr: COMPILED. Uthman: STANDARDISED copies (Mushaf Uthmani).","section":"Islamiyat","topic":"Caliphs"},{"id":72,"question_text":"Caliphs: Which Caliph is known as ''Dhun-Nurayn'' (Possessor of Two Lights)?","option_a":"Hazrat Umar (RA)","option_b":"Hazrat Ali (RA)","option_c":"Hazrat Abu Bakr (RA)","option_d":"Hazrat Uthman (RA)","correct_option":"D","explanation":"He married two daughters of the Prophet (PBUH), Ruqayyah and then Umm Kulthum. ⚡ Trick: Siddiq (Abu Bakr), Farooq (Umar), Dhun-Nurayn (Uthman), Haydar/Asadullah (Ali).","section":"Islamiyat","topic":"Caliphs"},{"id":73,"question_text":"Caliphs: The Hijri calendar was introduced in the caliphate of:","option_a":"Hazrat Uthman (RA)","option_b":"Hazrat Umar (RA)","option_c":"Hazrat Ali (RA)","option_d":"Hazrat Abu Bakr (RA)","correct_option":"B","explanation":"He fixed the Hijrah as the start of the Islamic calendar, beginning with Muharram. ⚡ Trick: Umar = administrative firsts: Hijri calendar, Diwan, police, cantonments.","section":"Islamiyat","topic":"Caliphs"},{"id":74,"question_text":"Companions: Who was the first Mu''adhdhin (caller to prayer) of Islam?","option_a":"Hazrat Khalid bin Walid (RA)","option_b":"Hazrat Abu Hurairah (RA)","option_c":"Hazrat Bilal ibn Rabah (RA)","option_d":"Hazrat Salman Farsi (RA)","correct_option":"C","explanation":"⚡ Trick: Bilal = Adhan. Khalid bin Walid = \"Sword of Allah\". Salman Farsi = Khandaq trench idea.","section":"Islamiyat","topic":"Companions"},{"id":75,"question_text":"Seerah: The first woman to accept Islam was:","option_a":"Hazrat Fatimah (RA)","option_b":"Hazrat Khadijah (RA)","option_c":"Hazrat Aisha (RA)","option_d":"Hazrat Sumayyah (RA)","correct_option":"B","explanation":"(Abu Bakr was the first free adult man, Ali the first child.) ⚡ Trick: First woman: Khadijah. First man: Abu Bakr. First child: Ali. First woman martyr: Sumayyah.","section":"Islamiyat","topic":"Seerah"},{"id":76,"question_text":"Pillars: The rate of Zakat on savings, gold and silver (above nisab, held for a year) is:","option_a":"10%","option_b":"2.5% (1/40)","option_c":"5%","option_d":"20%","correct_option":"B","explanation":"Ushr on rain-fed crops is 10%. ⚡ Trick: Zakat 2.5%, Ushr 10% / 5%, Khums (booty) 20%.","section":"Islamiyat","topic":"Pillars"},{"id":77,"question_text":"Fiqh: In order of importance, the third source of Islamic law is:","option_a":"Ijma (consensus)","option_b":"Quran","option_c":"Sunnah","option_d":"Qiyas (analogy)","correct_option":"A","explanation":"Sources: 1) Quran 2) Sunnah 3) Ijma 4) Qiyas. ⚡ Trick: Remember QSIQ.","section":"Islamiyat","topic":"Fiqh"},{"id":78,"question_text":"Hadith: The famous collection of Hadith by Imam Bukhari is called:","option_a":"Al-Jami'' al-Sahih","option_b":"Al-Muwatta","option_c":"Sunan Abu Dawud","option_d":"Jami'' at-Tirmidhi","correct_option":"A","explanation":"Sahih al-Bukhari is regarded as the most authentic after the Quran. Al-Muwatta is by Imam Malik. ⚡ Trick: Bukhari → Sahih; Muslim → Sahih Muslim; Malik → Muwatta; Tirmidhi → Jami''.","section":"Islamiyat","topic":"Hadith"},{"id":79,"question_text":"Seerah: The Holy Prophet (PBUH) migrated from Makkah to Madinah in the year:","option_a":"632 CE","option_b":"622 CE (1 A.H.)","option_c":"610 CE","option_d":"630 CE","correct_option":"B","explanation":"⚡ Trick: 610 = first revelation; 622 = Hijrah; 630 = Makkah conquered; 632 = demise.","section":"Islamiyat","topic":"Seerah"},{"id":80,"question_text":"Pillars: Zakat can be spent on how many categories of recipients mentioned in Surah At-Tawbah (9:60)?","option_a":"10","option_b":"4","option_c":"8","option_d":"5","correct_option":"C","explanation":"The verse names eight categories, including the poor, the needy, those in debt, and in the way of Allah. ⚡ Trick: Zakat has 8 recipients; Islam has 5 pillars; Quran has 114 Surahs. Don''t mix the numbers.","section":"Islamiyat","topic":"Pillars"},{"id":81,"question_text":"History: The Objectives Resolution was passed by the Constituent Assembly of Pakistan in:","option_a":"1954","option_b":"1947","option_c":"1949","option_d":"1950","correct_option":"C","explanation":"Moved by Liaquat Ali Khan, passed 12 March 1949. ⚡ Trick: Objectives Resolution = 1949. First Constitution = 1956.","section":"Pakistan Studies","topic":"History"},{"id":82,"question_text":"History: The All-India Muslim League was founded in 1906 at:","option_a":"Lucknow","option_b":"Lahore","option_c":"Dhaka","option_d":"Delhi","correct_option":"C","explanation":"Founded 30 December 1906 at the Educational Conference, with Nawab Salimullah Khan a leading figure. ⚡ Trick: 1906: Simla Deputation (October) → Muslim League (December, Dhaka).","section":"Pakistan Studies","topic":"History"},{"id":83,"question_text":"History: The Lucknow Pact (1916) was signed between:","option_a":"The Muslim League and the Indian National Congress","option_b":"The Muslim League and the British Government","option_c":"The Muslim League and the Unionist Party","option_d":"The Congress and the British Government","correct_option":"A","explanation":"Congress accepted separate electorates; Jinnah was called the \"Ambassador of Hindu-Muslim Unity\". ⚡ Trick: Lucknow 1916 = League + Congress.","section":"Pakistan Studies","topic":"History"},{"id":84,"question_text":"History: The Fourteen Points of Quaid-e-Azam were presented in:","option_a":"1935","option_b":"1929","option_c":"1927","option_d":"1930","correct_option":"B","explanation":"Announced March 1929 as a reply to the Nehru Report (1928). ⚡ Trick: Delhi Proposals 1927 → Nehru Report 1928 → Fourteen Points 1929 → Allahabad 1930.","section":"Pakistan Studies","topic":"History"},{"id":85,"question_text":"History: Pakistan came into existence on the 27th of which Islamic month?","option_a":"Rajab","option_b":"Shawwal","option_c":"Muharram","option_d":"Ramadan","correct_option":"D","explanation":"14 August 1947 corresponded to 27 Ramadan 1366 AH. ⚡ Trick: Don''t confuse with 27 Rajab (Mi''raj). Pakistan = 27 Ramadan.","section":"Pakistan Studies","topic":"History"},{"id":86,"question_text":"Constitution: The present Constitution of Pakistan was enforced on:","option_a":"23 March 1973","option_b":"14 August 1973","option_c":"10 April 1973","option_d":"12 March 1973","correct_option":"B","explanation":"Passed by the National Assembly on 10 April 1973. ⚡ Trick: Passed 10 April, enforced 14 August. Constitutions: 1956, 1962, 1973.","section":"Pakistan Studies","topic":"Constitution"},{"id":87,"question_text":"Personalities: Quaid-e-Azam Muhammad Ali Jinnah died on:","option_a":"14 August 1948","option_b":"11 September 1948","option_c":"25 December 1948","option_d":"23 March 1948","correct_option":"B","explanation":"Died in Karachi; born 25 December 1876. ⚡ Trick: 25 Dec is his birthday, not death.","section":"Pakistan Studies","topic":"Personalities"},{"id":88,"question_text":"Geography: The Indus Waters Treaty between Pakistan and India was signed in:","option_a":"1947","option_b":"1950","option_c":"1965","option_d":"1960","correct_option":"D","explanation":"Signed in Karachi, 19 September 1960, with World Bank mediation; Pakistan got the western rivers (Indus, Jhelum, Chenab). ⚡ Trick: Western rivers → Pakistan; eastern rivers (Ravi, Beas, Sutlej) → India.","section":"Pakistan Studies","topic":"Geography"},{"id":89,"question_text":"Geography: The largest province of Pakistan by area is:","option_a":"Balochistan","option_b":"Sindh","option_c":"Punjab","option_d":"Khyber Pakhtunkhwa","correct_option":"A","explanation":"About 44% of Pakistan''s area, smallest population. ⚡ Trick: Area: Balochistan > Punjab > Sindh > KP. Population: Punjab > Sindh > KP > Balochistan.","section":"Pakistan Studies","topic":"Geography"},{"id":90,"question_text":"Geography: The Karakoram Highway links Pakistan with China through the:","option_a":"Khunjerab Pass","option_b":"Bolan Pass","option_c":"Khyber Pass","option_d":"Lowari Pass","correct_option":"A","explanation":"The KKH (N-35) crosses into China here, the world''s highest paved international border crossing. ⚡ Trick: Khyber → Afghanistan; Bolan → Balochistan route; Khunjerab → China.","section":"Pakistan Studies","topic":"Geography"},{"id":91,"question_text":"Units: One horsepower (hp) is equal to:","option_a":"100 W","option_b":"746 W","option_c":"550 W","option_d":"1000 W","correct_option":"B","explanation":"⚡ Trick: Memorise 746. 1 kW ≈ 1.34 hp.","section":"Physics","topic":"Units"},{"id":92,"question_text":"Dynamics: A man of mass 60 kg stands on the floor of a lift accelerating upward at 2 m s⁻². His apparent weight is (g = 9.8 m s⁻²):","option_a":"468 N","option_b":"120 N","option_c":"708 N","option_d":"588 N","correct_option":"C","explanation":"N − mg = ma → N = m(g + a) = 60 × 11.8 = 708 N. ⚡ Trick: Lift accelerating UP → heavier: m(g + a). Accelerating DOWN → lighter: m(g − a).","section":"Physics","topic":"Dynamics"},{"id":93,"question_text":"Heat: How much heat is needed to raise the temperature of 2 kg of water by 10 °C? (c = 4200 J kg⁻¹ K⁻¹)","option_a":"8 400 J","option_b":"840 000 J","option_c":"84 000 J","option_d":"42 000 J","correct_option":"C","explanation":"Q = mcΔT = 2 × 4200 × 10. ⚡ Trick: 2 × 4200 = 8400; × 10 = 84 000. Count zeros carefully.","section":"Physics","topic":"Heat"},{"id":94,"question_text":"Sound: Sound waves cannot travel through:","option_a":"Air","option_b":"Water","option_c":"Steel","option_d":"A vacuum","correct_option":"D","explanation":"Sound is a mechanical wave and needs a medium. ⚡ Trick: Sound needs a medium; light does not. Sound is fastest in solids, slowest in gases.","section":"Physics","topic":"Sound"},{"id":95,"question_text":"Optics: The refractive index of glass is 1.5. The speed of light in glass is (c = 3×10⁸ m s⁻¹):","option_a":"2×10⁸ m s⁻¹","option_b":"3×10⁸ m s⁻¹","option_c":"4.5×10⁸ m s⁻¹","option_d":"1.5×10⁸ m s⁻¹","correct_option":"A","explanation":"v = c/n = 3×10⁸/1.5. ⚡ Trick: Light slows in a denser medium, so the answer must be LESS than 3×10⁸.","section":"Physics","topic":"Optics"},{"id":96,"question_text":"Optics: A convex lens forms a real, inverted image of the same size as the object when the object is placed at:","option_a":"f","option_b":"2f","option_c":"Beyond 2f","option_d":"Between f and 2f","correct_option":"B","explanation":"Object at 2f → image at 2f, real, inverted, equal in size. ⚡ Trick: At 2f = same-size case; at f the image goes to infinity; beyond 2f the image is diminished.","section":"Physics","topic":"Optics"},{"id":97,"question_text":"Optics: The critical angle of a medium of refractive index 2 is:","option_a":"30°","option_b":"90°","option_c":"45°","option_d":"60°","correct_option":"A","explanation":"sin C = 1/n = 1/2 → C = 30°. ⚡ Trick: Larger n → smaller critical angle.","section":"Physics","topic":"Optics"},{"id":98,"question_text":"Electricity: An electric heater of 2 kW is used for 3 hours. If one unit (1 kWh) costs Rs. 40, the cost of electricity used is:","option_a":"Rs. 80","option_b":"Rs. 240","option_c":"Rs. 24","option_d":"Rs. 120","correct_option":"B","explanation":"2 kW × 3 h = 6 kWh; 6 × 40 = 240. ⚡ Trick: Cost = kW × hours × rate. Don''t convert to joules unless asked.","section":"Physics","topic":"Electricity"},{"id":99,"question_text":"Magnetism: The working of an electric motor is based on:","option_a":"The heating effect of current","option_b":"Electrolysis","option_c":"Electromagnetic induction","option_d":"The force on a current-carrying conductor in a magnetic field","correct_option":"D","explanation":"Torque on a coil (Fleming''s left-hand rule). ⚡ Trick: MOTOR → force on current (left hand). GENERATOR → induction (right hand).","section":"Physics","topic":"Magnetism"},{"id":100,"question_text":"Nuclear: Which of the following radiations has the greatest penetrating power?","option_a":"Gamma rays","option_b":"Alpha particles","option_c":"All have equal penetration","option_d":"Beta particles","correct_option":"A","explanation":"Alpha is stopped by paper, beta by thin aluminium, gamma needs thick lead or concrete. ⚡ Trick: Penetration: γ > β > α. Ionising power: α > β > γ.","section":"Physics","topic":"Nuclear"}]'::jsonb)
on conflict (test_slug) do update set questions = excluded.questions, updated_at = now();

